import {
  createContext,
  useContext,
  useState,
  useCallback,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { useControllableState, useTheme } from 'jind-ui-kit';

interface AccordionContextValue {
  expandedItems: string[];
  toggle: (value: string) => void;
  multiple: boolean;
}

const AccordionContext = createContext<AccordionContextValue>({
  expandedItems: [],
  toggle: () => {},
  multiple: false,
});

export interface AccordionProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (value: string[]) => void;
  multiple?: boolean;
  style?: CSSProperties;
  children: ReactNode;
  ref?: React.Ref<HTMLDivElement>;
}

export function Accordion(
  { value, defaultValue = [], onChange, multiple = false, style, children, ref, ...rest }: AccordionProps,
) {
  const theme = useTheme();
  const [expandedItems, setExpandedItems] = useControllableState(value, defaultValue, onChange);

  const toggle = useCallback(
    (itemValue: string) => {
      setExpandedItems((prev) => {
        const isOpen = prev.includes(itemValue);
        if (isOpen) return prev.filter((v) => v !== itemValue);
        return multiple ? [...prev, itemValue] : [itemValue];
      });
    },
    [multiple, setExpandedItems],
  );

  return (
    <AccordionContext.Provider value={{ expandedItems, toggle, multiple }}>
      <div
        ref={ref}
        style={{
          borderRadius: theme.radius.md,
          border: `1px solid ${theme.semantic.border.subtle}`,
          overflow: 'hidden',
          ...style,
        }}
        {...rest}
      >
        {children}
      </div>
    </AccordionContext.Provider>
  );
}

export interface AccordionItemProps {
  value: string;
  style?: CSSProperties;
  children: ReactNode;
  ref?: React.Ref<HTMLDivElement>;
}

const AccordionItemContext = createContext<{ value: string; isOpen: boolean }>({
  value: '',
  isOpen: false,
});

export function AccordionItem(
  { value, style, children, ref, ...rest }: AccordionItemProps,
) {
  const theme = useTheme();
  const { expandedItems } = useContext(AccordionContext);
  const isOpen = expandedItems.includes(value);

  return (
    <AccordionItemContext.Provider value={{ value, isOpen }}>
      <div
        ref={ref}
        style={{
          borderBottom: `1px solid ${theme.semantic.border.subtle}`,
          ...style,
        }}
        {...rest}
      >
        {children}
      </div>
    </AccordionItemContext.Provider>
  );
}

export interface AccordionTriggerProps {
  style?: CSSProperties;
  children: ReactNode;
  ref?: React.Ref<HTMLButtonElement>;
}

export function AccordionTrigger(
  { style, children, ref, ...rest }: AccordionTriggerProps,
) {
  const theme = useTheme();
  const { toggle } = useContext(AccordionContext);
  const { value, isOpen } = useContext(AccordionItemContext);
  const [hover, setHover] = useState(false);

  return (
    <button
      ref={ref}
      type="button"
      aria-expanded={isOpen}
      onClick={() => toggle(value)}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        width: '100%',
        padding: `${theme.space[6]}px ${theme.controlPadding.field}px`,
        border: 'none',
        background: hover ? theme.semantic.surface.hover : theme.semantic.surface.card,
        cursor: 'pointer',
        fontFamily: theme.fontFamily.sans,
        fontSize: theme.fontSize[14],
        fontWeight: theme.fontWeight.medium,
        color: theme.semantic.text.primary,
        transition: `background-color ${theme.duration.fast}ms ${theme.easing.standard}`,
        ...style,
      }}
      {...rest}
    >
      <span>{children}</span>
      <i
        className={isOpen ? 'iconoir-nav-arrow-up' : 'iconoir-nav-arrow-down'}
        aria-hidden="true"
        style={{
          fontSize: 18,
          color: theme.semantic.icon.default,
          transition: `transform ${theme.duration.base}ms ${theme.easing.standard}`,
        }}
      />
    </button>
  );
}

export interface AccordionContentProps {
  style?: CSSProperties;
  children: ReactNode;
  ref?: React.Ref<HTMLDivElement>;
}

export function AccordionContent(
  { style, children, ref, ...rest }: AccordionContentProps,
) {
  const theme = useTheme();
  const { isOpen } = useContext(AccordionItemContext);

  if (!isOpen) return null;

  return (
    <div
      ref={ref}
      role="region"
      style={{
        padding: `${theme.space[4]}px ${theme.controlPadding.field}px ${theme.space[7]}px`,
        fontFamily: theme.fontFamily.sans,
        fontSize: theme.fontSize[14],
        lineHeight: theme.lineHeight.normal,
        color: theme.semantic.text.secondary,
        ...style,
      }}
      {...rest}
    >
      {children}
    </div>
  );
}

import { type CSSProperties, type ReactNode, type Ref } from 'react';
import { useTheme, type Tone } from 'jind-ui-kit';

export interface AlertProps {
  ref?: Ref<HTMLDivElement>;
  tone?: Tone;
  title?: string;
  children: ReactNode;
  icon?: string;
  onDismiss?: () => void;
  variant?: 'subtle' | 'solid';
  style?: CSSProperties;
}

function getToneColors(tone: Tone, theme: ReturnType<typeof useTheme>) {
  const { colors } = theme;
  const map: Record<Tone, { bg: string; text: string; border: string; solidBg: string; solidText: string }> = {
    neutral: { bg: colors.gray[50], text: colors.gray[700], border: colors.gray[300], solidBg: colors.gray[700], solidText: colors.gray[0] },
    primary: { bg: colors.blue[50], text: colors.blue[700], border: colors.blue[500], solidBg: colors.blue[600], solidText: colors.gray[0] },
    danger: { bg: colors.red[50], text: colors.red[600], border: colors.red[500], solidBg: colors.red[600], solidText: colors.gray[0] },
    success: { bg: colors.green[50], text: colors.green[500], border: colors.green[500], solidBg: colors.green[500], solidText: colors.gray[0] },
    warning: { bg: colors.amber[50], text: colors.amber[600], border: colors.amber[500], solidBg: colors.amber[500], solidText: colors.gray[0] },
    info: { bg: colors.teal[50], text: colors.teal[600], border: colors.teal[600], solidBg: colors.teal[600], solidText: colors.gray[0] },
    accent: { bg: colors.purple[50], text: colors.purple[500], border: colors.purple[500], solidBg: colors.purple[500], solidText: colors.gray[0] },
    brand: { bg: colors.blue[50], text: colors.blue[700], border: colors.blue[500], solidBg: colors.blue[600], solidText: colors.gray[0] },
  };
  return map[tone];
}

export function Alert({
  ref,
  tone = 'neutral',
  title,
  children,
  icon,
  onDismiss,
  variant = 'subtle',
  style,
}: AlertProps) {
  const theme = useTheme();
  const toneColors = getToneColors(tone, theme);
  const isSubtle = variant === 'subtle';

  const role = tone === 'danger' || tone === 'warning' ? 'alert' : 'status';

  const containerStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'flex-start',
    gap: theme.space[6],
    padding: `${theme.space[6]}px ${theme.space[7]}px`,
    backgroundColor: isSubtle ? toneColors.bg : toneColors.solidBg,
    borderLeft: isSubtle ? `4px solid ${toneColors.border}` : undefined,
    borderRadius: theme.radius.md,
    fontFamily: theme.fontFamily.sans,
    boxSizing: 'border-box' as const,
    ...style,
  };

  const iconStyle: CSSProperties = {
    fontSize: 16,
    lineHeight: 1,
    flexShrink: 0,
    color: isSubtle ? toneColors.text : toneColors.solidText,
    paddingTop: 2,
  };

  const bodyStyle: CSSProperties = {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: theme.space[4],
  };

  const titleStyle: CSSProperties = {
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.bold,
    lineHeight: theme.lineHeight.normal,
    color: isSubtle ? toneColors.text : toneColors.solidText,
    margin: 0,
  };

  const descriptionStyle: CSSProperties = {
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    lineHeight: theme.lineHeight.normal,
    color: isSubtle ? toneColors.text : toneColors.solidText,
    opacity: isSubtle ? 1 : 0.9,
  };

  const dismissStyle: CSSProperties = {
    background: 'none',
    border: 'none',
    padding: theme.space[2],
    cursor: 'pointer',
    fontSize: 14,
    lineHeight: 1,
    color: isSubtle ? toneColors.text : toneColors.solidText,
    flexShrink: 0,
    opacity: 0.7,
  };

  return (
    <div ref={ref} role={role} style={containerStyle}>
      {icon != null && <span style={iconStyle}>{icon}</span>}
      <div style={bodyStyle}>
        {title != null && <p style={titleStyle}>{title}</p>}
        <div style={descriptionStyle}>{children}</div>
      </div>
      {onDismiss != null && (
        <button
          type="button"
          onClick={onDismiss}
          style={dismissStyle}
          aria-label="Dismiss alert"
        >
          &#x2715;
        </button>
      )}
    </div>
  );
}

import {
  useEffect,
  useRef,
  useCallback,
  useId,
  type CSSProperties,
  type Ref,
} from 'react';
import { transition } from 'jind-ui-kit/styles';
import { Portal, useFocusTrap, useTheme, type Tone } from 'jind-ui-kit';

export interface AlertDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
  cancelLabel?: string;
  confirmLabel?: string;
  onConfirm: () => void;
  onCancel?: () => void;
  tone?: Tone;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

function getToneButtonColors(tone: Tone, theme: ReturnType<typeof useTheme>) {
  const { colors } = theme;
  const map: Record<Tone, { bg: string; text: string }> = {
    neutral: { bg: colors.gray[700], text: colors.gray[0] },
    primary: { bg: colors.blue[600], text: colors.gray[0] },
    danger: { bg: colors.red[500], text: colors.gray[0] },
    success: { bg: colors.green[500], text: colors.gray[0] },
    warning: { bg: colors.amber[500], text: colors.gray[0] },
    info: { bg: colors.teal[600], text: colors.gray[0] },
    accent: { bg: colors.purple[500], text: colors.gray[0] },
    brand: { bg: colors.blue[600], text: colors.gray[0] },
  };
  return map[tone];
}

export function AlertDialog({
  open,
  onOpenChange,
  title,
  description,
  cancelLabel = 'Cancel',
  confirmLabel = 'Confirm',
  onConfirm,
  onCancel,
  tone = 'danger',
  style,
  ref,
}: AlertDialogProps) {
  const theme = useTheme();
  const contentRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const descId = useId();
  const toneColors = getToneButtonColors(tone, theme);

  useFocusTrap(contentRef, open);

  const handleClose = useCallback(() => {
    onOpenChange(false);
  }, [onOpenChange]);

  const handleCancel = useCallback(() => {
    onCancel?.();
    handleClose();
  }, [onCancel, handleClose]);

  const handleConfirm = useCallback(() => {
    onConfirm();
    handleClose();
  }, [onConfirm, handleClose]);

  useEffect(() => {
    if (!open) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        handleCancel();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [open, handleCancel]);

  if (!open) return null;

  const backdropStyle: CSSProperties = {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    zIndex: 1000,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  };

  const dialogStyle: CSSProperties = {
    backgroundColor: theme.semantic.surface.card,
    borderRadius: theme.radius.lg,
    boxShadow: theme.shadow.menu,
    width: 420,
    maxWidth: '90vw',
    boxSizing: 'border-box' as const,
    ...style,
  };

  const bodyStyle: CSSProperties = {
    padding: theme.space[9],
  };

  const titleStyle: CSSProperties = {
    fontSize: theme.fontSize[16],
    fontWeight: theme.fontWeight.bold,
    lineHeight: theme.lineHeight.normal,
    color: theme.semantic.text.primary,
    fontFamily: theme.fontFamily.sans,
    margin: 0,
  };

  const descriptionStyle: CSSProperties = {
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    lineHeight: theme.lineHeight.normal,
    color: theme.semantic.text.secondary,
    fontFamily: theme.fontFamily.sans,
    margin: 0,
    marginTop: theme.space[4],
  };

  const footerStyle: CSSProperties = {
    display: 'flex',
    justifyContent: 'flex-end',
    gap: theme.space[6],
    padding: `${theme.space[7]}px ${theme.space[9]}px`,
    borderTop: `1px solid ${theme.semantic.border.subtle}`,
  };

  const baseButtonStyle: CSSProperties = {
    padding: `${theme.space[4]}px ${theme.controlPadding.button}px`,
    borderRadius: theme.radius.md,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.medium,
    fontFamily: theme.fontFamily.sans,
    cursor: 'pointer',
    border: 'none',
    transition: transition('background-color', 'opacity'),
    lineHeight: theme.lineHeight.normal,
  };

  const cancelButtonStyle: CSSProperties = {
    ...baseButtonStyle,
    backgroundColor: theme.semantic.surface.subtle,
    color: theme.semantic.text.primary,
    border: `1px solid ${theme.semantic.border.default}`,
  };

  const confirmButtonStyle: CSSProperties = {
    ...baseButtonStyle,
    backgroundColor: toneColors.bg,
    color: toneColors.text,
  };

  return (
    <Portal>
      <div style={backdropStyle} ref={ref}>
        <div
          ref={contentRef}
          role="alertdialog"
          aria-modal="true"
          aria-labelledby={titleId}
          aria-describedby={description ? descId : undefined}
          style={dialogStyle}
        >
          <div style={bodyStyle}>
            <h2 id={titleId} style={titleStyle}>
              {title}
            </h2>
            {description != null && (
              <p id={descId} style={descriptionStyle}>
                {description}
              </p>
            )}
          </div>
          <div style={footerStyle}>
            <button type="button" style={cancelButtonStyle} onClick={handleCancel}>
              {cancelLabel}
            </button>
            <button type="button" style={confirmButtonStyle} onClick={handleConfirm}>
              {confirmLabel}
            </button>
          </div>
        </div>
      </div>
    </Portal>
  );
}

import { type CSSProperties } from 'react';
import { useTheme } from 'jind-ui-kit';

export interface AvatarProps {
  src?: string;
  name?: string;
  size?: 'sm' | 'md' | 'lg';
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

const sizeMap = { sm: 24, md: 32, lg: 40 } as const;
const fontSizeMap = { sm: 10, md: 12, lg: 14 } as const;

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0) return '';
  if (parts.length === 1) return parts[0][0].toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

export function Avatar(
  { src, name, size = 'md', style, ref, ...rest }: AvatarProps,
) {
  const theme = useTheme();
  const px = sizeMap[size];

  const containerStyle: CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: px,
    height: px,
    borderRadius: '50%',
    overflow: 'hidden',
    flexShrink: 0,
    backgroundColor: src ? undefined : theme.colors.gray[150],
    ...style,
  };

  if (src) {
    return (
      <div ref={ref} style={containerStyle} {...rest}>
        <img
          src={src}
          alt={name ?? ''}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            display: 'block',
          }}
        />
      </div>
    );
  }

  const initials = name ? getInitials(name) : '';

  return (
    <div ref={ref} style={containerStyle} data-testid="avatar" {...rest}>
      {initials && (
        <span
          style={{
            fontFamily: theme.typeVariants.caption.fontFamily,
            fontSize: fontSizeMap[size],
            fontWeight: 500,
            lineHeight: 1,
            color: theme.colors.gray[600],
            userSelect: 'none',
          }}
        >
          {initials}
        </span>
      )}
    </div>
  );
}

import type { CSSProperties, ReactNode } from 'react';
import { useTheme, type JindTheme, type Tone } from 'jind-ui-kit';

export interface BadgeProps {
  tone?: Tone;
  dot?: boolean;
  onDismiss?: () => void;
  children: ReactNode;
  style?: CSSProperties;
}

function getToneColors(tone: Tone, theme: JindTheme) {
  switch (tone) {
    case 'info':
      return {
        bg: theme.colors.teal[50],
        fg: theme.colors.teal[600],
        dot: theme.colors.teal[600],
      };
    case 'warning':
      return {
        bg: theme.colors.amber[50],
        fg: theme.colors.amber[600],
        dot: theme.colors.amber[500],
      };
    case 'success':
      return {
        bg: theme.colors.green[50],
        fg: theme.colors.green[500],
        dot: theme.colors.green[500],
      };
    case 'danger':
      return {
        bg: theme.colors.red[50],
        fg: theme.colors.red[600],
        dot: theme.colors.red[500],
      };
    case 'accent':
      return {
        bg: theme.colors.purple[50],
        fg: theme.colors.purple[500],
        dot: theme.colors.purple[500],
      };
    case 'brand':
    case 'primary':
      return {
        bg: theme.colors.blue[50],
        fg: theme.colors.blue[600],
        dot: theme.colors.blue[500],
      };
    case 'neutral':
    default:
      return {
        bg: theme.semantic.surface.quiet,
        fg: theme.colors.gray[800],
        dot: theme.colors.gray[500],
      };
  }
}

export function Badge({
  tone = 'info',
  dot,
  onDismiss,
  children,
  style,
}: BadgeProps) {
  const theme = useTheme();
  const toneColors = getToneColors(tone, theme);

  const badgeStyle: CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    height: 26,
    paddingLeft: 8,
    paddingRight: 8,
    paddingTop: 0,
    paddingBottom: 0,
    borderRadius: theme.radius.xs,
    backgroundColor: toneColors.bg,
    color: toneColors.fg,
    fontFamily: theme.typeVariants.caption.fontFamily,
    fontSize: theme.typeVariants.caption.fontSize,
    fontWeight: theme.typeVariants.caption.fontWeight,
    lineHeight: theme.typeVariants.caption.lineHeight,
    gap: 8,
    boxSizing: 'border-box',
    ...style,
  };

  const dotStyle: CSSProperties = {
    width: 10,
    height: 10,
    borderRadius: '50%',
    backgroundColor: toneColors.dot,
    flexShrink: 0,
  };

  const dismissStyle: CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: 13,
    opacity: 0.65,
    cursor: 'pointer',
    background: 'none',
    border: 'none',
    padding: 0,
    margin: 0,
    color: 'inherit',
    lineHeight: 1,
  };

  return (
    <span style={badgeStyle} data-testid="badge">
      {dot && <span data-testid="badge-dot" style={dotStyle} />}
      {children}
      {onDismiss && (
        <button
          type="button"
          data-testid="badge-dismiss"
          style={dismissStyle}
          onClick={onDismiss}
          aria-label="Dismiss"
        >
          {'✕'}
        </button>
      )}
    </span>
  );
}

import { type CSSProperties, type ReactNode, type Ref } from 'react';
import { useTheme, type Tone } from 'jind-ui-kit';

export interface BannerProps {
  ref?: Ref<HTMLDivElement>;
  tone?: Tone;
  children: ReactNode;
  icon?: string;
  action?: ReactNode;
  onDismiss?: () => void;
  position?: 'top' | 'bottom' | 'inline';
  style?: CSSProperties;
}

function getToneColors(tone: Tone, theme: ReturnType<typeof useTheme>) {
  const { colors } = theme;
  const map: Record<Tone, { bg: string; text: string; border: string }> = {
    neutral: { bg: colors.gray[50], text: colors.gray[700], border: colors.gray[200] },
    primary: { bg: colors.blue[50], text: colors.blue[700], border: colors.blue[200] },
    danger: { bg: colors.red[50], text: colors.red[500], border: colors.red[50] },
    success: { bg: colors.green[50], text: colors.green[500], border: colors.green[50] },
    warning: { bg: colors.amber[50], text: colors.amber[600], border: colors.amber[50] },
    info: { bg: colors.teal[50], text: colors.teal[600], border: colors.teal[50] },
    accent: { bg: colors.purple[50], text: colors.purple[500], border: colors.purple[50] },
    brand: { bg: colors.blue[50], text: colors.blue[500], border: colors.blue[200] },
  };
  return map[tone];
}

export function Banner({
  ref,
  tone = 'neutral',
  children,
  icon,
  action,
  onDismiss,
  position = 'inline',
  style,
}: BannerProps) {
  const theme = useTheme();
  const toneColors = getToneColors(tone, theme);

  const isFixed = position !== 'inline';

  const containerStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    padding: '12px 16px',
    backgroundColor: toneColors.bg,
    borderBottom: isFixed && position === 'top' ? `1px solid ${toneColors.border}` : undefined,
    borderTop: isFixed && position === 'bottom' ? `1px solid ${toneColors.border}` : undefined,
    border: !isFixed ? `1px solid ${toneColors.border}` : undefined,
    borderRadius: !isFixed ? theme.radius.md : undefined,
    fontFamily: theme.fontFamily.sans,
    boxSizing: 'border-box' as const,
    ...(isFixed && {
      position: 'fixed' as const,
      left: 0,
      right: 0,
      zIndex: 1000,
      ...(position === 'top' ? { top: 0 } : { bottom: 0 }),
    }),
    ...style,
  };

  const iconStyle: CSSProperties = {
    fontSize: 16,
    lineHeight: 1,
    flexShrink: 0,
  };

  const bodyStyle: CSSProperties = {
    flex: 1,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    lineHeight: theme.lineHeight.normal,
    color: toneColors.text,
  };

  const dismissStyle: CSSProperties = {
    background: 'none',
    border: 'none',
    padding: 4,
    cursor: 'pointer',
    fontSize: 14,
    lineHeight: 1,
    color: toneColors.text,
    flexShrink: 0,
    opacity: 0.7,
  };

  return (
    <div ref={ref} role="banner" style={containerStyle}>
      {icon != null && <span style={iconStyle}>{icon}</span>}
      <div style={bodyStyle}>{children}</div>
      {action != null && <div style={{ flexShrink: 0 }}>{action}</div>}
      {onDismiss != null && (
        <button
          type="button"
          onClick={onDismiss}
          style={dismissStyle}
          aria-label="Dismiss banner"
        >
          &#x2715;
        </button>
      )}
    </div>
  );
}

import { type CSSProperties, type ReactNode, type Ref } from 'react';
import { useTheme } from 'jind-ui-kit';

export interface BreadcrumbItem {
  label: string;
  href?: string;
  onClick?: () => void;
}

export interface BreadcrumbsProps {
  ref?: Ref<HTMLElement>;
  items: BreadcrumbItem[];
  separator?: ReactNode;
  maxItems?: number;
  style?: CSSProperties;
}

function getVisibleItems(items: readonly BreadcrumbItem[], maxItems: number | undefined): readonly BreadcrumbItem[] {
  if (maxItems == null || items.length <= maxItems) {
    return items;
  }
  const first = items[0];
  const lastCount = maxItems - 1;
  const tail = items.slice(items.length - lastCount);
  return [first, ...tail];
}

export function Breadcrumbs({
  ref,
  items,
  separator = '/',
  maxItems,
  style,
}: BreadcrumbsProps) {
  const theme = useTheme();
  const showEllipsis = maxItems != null && items.length > maxItems;
  const visibleItems = getVisibleItems(items, maxItems);

  const navStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    ...style,
  };

  const listStyle: CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    alignItems: 'center',
    gap: theme.space[2],
    listStyle: 'none',
    margin: 0,
    padding: 0,
  };

  const separatorStyle: CSSProperties = {
    color: theme.semantic.text.muted,
    userSelect: 'none',
    flexShrink: 0,
  };

  const linkStyle: CSSProperties = {
    color: theme.semantic.fill.primary,
    textDecoration: 'none',
    cursor: 'pointer',
    fontWeight: theme.fontWeight.regular,
    background: 'none',
    border: 'none',
    padding: 0,
    font: 'inherit',
  };

  const activeStyle: CSSProperties = {
    color: theme.semantic.text.primary,
    fontWeight: theme.fontWeight.bold,
  };

  const ellipsisStyle: CSSProperties = {
    color: theme.semantic.text.muted,
    letterSpacing: '0.1em',
  };

  const renderSeparator = (key: string) => (
    <li key={key} role="presentation" aria-hidden="true" style={separatorStyle}>
      {separator}
    </li>
  );

  const renderItem = (item: BreadcrumbItem, isLast: boolean) => {
    if (isLast) {
      return (
        <span aria-current="page" style={activeStyle}>
          {item.label}
        </span>
      );
    }

    if (item.href != null) {
      return (
        <a href={item.href} onClick={item.onClick} style={linkStyle}>
          {item.label}
        </a>
      );
    }

    if (item.onClick != null) {
      return (
        <button type="button" onClick={item.onClick} style={linkStyle}>
          {item.label}
        </button>
      );
    }

    return <span style={{ color: theme.semantic.text.muted }}>{item.label}</span>;
  };

  const elements: ReactNode[] = [];

  if (showEllipsis) {
    // First item
    elements.push(
      <li key="item-first">{renderItem(visibleItems[0], false)}</li>,
    );
    elements.push(renderSeparator('sep-first'));

    // Ellipsis
    elements.push(
      <li key="ellipsis" style={ellipsisStyle} aria-hidden="true">
        {'...'}
      </li>,
    );
    elements.push(renderSeparator('sep-ellipsis'));

    // Remaining tail items
    for (let i = 1; i < visibleItems.length; i++) {
      const isLast = i === visibleItems.length - 1;
      elements.push(
        <li key={`item-${String(i)}`}>{renderItem(visibleItems[i], isLast)}</li>,
      );
      if (!isLast) {
        elements.push(renderSeparator(`sep-${String(i)}`));
      }
    }
  } else {
    for (let i = 0; i < visibleItems.length; i++) {
      const isLast = i === visibleItems.length - 1;
      elements.push(
        <li key={`item-${String(i)}`}>{renderItem(visibleItems[i], isLast)}</li>,
      );
      if (!isLast) {
        elements.push(renderSeparator(`sep-${String(i)}`));
      }
    }
  }

  return (
    <nav ref={ref} aria-label="Breadcrumb" style={navStyle}>
      <ol style={listStyle}>
        {elements}
      </ol>
    </nav>
  );
}

import {
  useState,
  type ElementType,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface ButtonOwnProps {
  variant?: 'primary' | 'secondary';
  size?: 'md' | 'sm';
  iconLeft?: string;
  iconRight?: string;
  disabled?: boolean;
  fullWidth?: boolean;
  as?: ElementType;
  children?: ReactNode;
  style?: CSSProperties;
  ref?: React.Ref<HTMLElement>;
}

export type ButtonProps<E extends ElementType = 'button'> = ButtonOwnProps &
  Omit<React.ComponentPropsWithoutRef<E>, keyof ButtonOwnProps>;

const sizeConfig = {
  md: { height: 44, paddingX: 22, iconSize: 20 },
  sm: { height: 32, paddingX: 14, iconSize: 16 },
} as const;

export function Button({
  as: Component = 'button',
  variant = 'primary',
  size = 'md',
  iconLeft,
  iconRight,
  disabled = false,
  fullWidth = false,
  style,
  children,
  onClick,
  ref,
  ...rest
}: ButtonProps) {
  const theme = useTheme();
  const [hovered, setHovered] = useState(false);
  const [active, setActive] = useState(false);
  const [focused, setFocused] = useState(false);

  const config = sizeConfig[size];
  const hasChildren = children != null && children !== '';
  const iconOnly = !hasChildren && (iconLeft != null || iconRight != null);

  const transitionValue = transition(
    'background-color',
    'border-color',
    'color',
    'box-shadow',
  );

  function getVariantStyles(): CSSProperties {
    if (variant === 'primary') {
      let background = theme.semantic.fill.primary;
      if (disabled) {
        background = theme.semantic.fill.disabled;
      } else if (active) {
        background = theme.semantic.fill.primaryActive;
      } else if (hovered) {
        background = theme.semantic.fill.primaryHover;
      }

      return {
        background,
        color: theme.semantic.text.inverse,
        border: '1px solid transparent',
      };
    }

    // secondary
    let background = theme.semantic.surface.card;
    if (!disabled) {
      if (active) {
        background = theme.semantic.surface.pressed;
      } else if (hovered) {
        background = theme.semantic.surface.subtle;
      }
    }

    return {
      background,
      color: theme.semantic.text.primary,
      border: `1px solid ${theme.semantic.border.subtle}`,
      boxShadow: theme.shadow.xs,
      ...(disabled ? { opacity: 0.5 } : {}),
    };
  }

  const variantStyles = getVariantStyles();

  let boxShadow = variantStyles.boxShadow as string | undefined;
  if (focused && !disabled) {
    boxShadow = boxShadow
      ? `${boxShadow}, ${theme.focusRing.primary}`
      : theme.focusRing.primary;
  }

  const buttonStyle: CSSProperties = mergeStyles(
    {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: hasChildren ? 10 : 0,
      height: config.height,
      padding: iconOnly ? 0 : `0 ${config.paddingX}px`,
      width: iconOnly ? config.height : fullWidth ? '100%' : undefined,
      borderRadius: theme.radius.sm,
      fontFamily: theme.typeVariants.control.fontFamily,
      fontSize: theme.typeVariants.control.fontSize,
      fontWeight: theme.typeVariants.control.fontWeight,
      lineHeight: theme.typeVariants.control.lineHeight,
      cursor: disabled ? 'not-allowed' : 'pointer',
      outline: 'none',
      textDecoration: 'none',
      boxSizing: 'border-box',
      transition: transitionValue,
    },
    variantStyles,
    { boxShadow },
    style,
  );

  function handleMouseEnter() {
    if (!disabled) setHovered(true);
  }
  function handleMouseLeave() {
    setHovered(false);
    setActive(false);
  }
  function handleMouseDown() {
    if (!disabled) setActive(true);
  }
  function handleMouseUp() {
    setActive(false);
  }
  function handleFocus() {
    setFocused(true);
  }
  function handleBlur() {
    setFocused(false);
  }
  function handleClick(e: React.MouseEvent<HTMLButtonElement>) {
    if (disabled) return;
    (onClick as ((e: React.MouseEvent) => void) | undefined)?.(e);
  }

  const iconEl = (name: string) => (
    <i
      className={`iconoir-${name}`}
      style={{ fontSize: config.iconSize }}
      aria-hidden="true"
    />
  );

  return (
    <Component
      ref={ref}
      style={buttonStyle}
      disabled={Component === 'button' ? disabled : undefined}
      aria-disabled={disabled || undefined}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onFocus={handleFocus}
      onBlur={handleBlur}
      onClick={handleClick}
      {...rest}
    >
      {iconLeft && iconEl(iconLeft)}
      {children}
      {iconRight && iconEl(iconRight)}
    </Component>
  );
}

import {
  type CSSProperties,
  type ReactNode,
  Children,
  cloneElement,
  isValidElement,
  type ReactElement,
} from 'react';
import { useTheme, type ButtonProps } from 'jind-ui-kit';

export interface ButtonGroupProps {
  children: ReactNode;
  size?: 'sm' | 'md';
  variant?: 'primary' | 'secondary';
  orientation?: 'horizontal' | 'vertical';
  attached?: boolean;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function ButtonGroup({
  children,
  size,
  variant,
  orientation = 'horizontal',
  attached = true,
  style,
  ref,
}: ButtonGroupProps) {
  const theme = useTheme();
  const isVertical = orientation === 'vertical';

  const containerStyle: CSSProperties = {
    display: 'inline-flex',
    flexDirection: isVertical ? 'column' : 'row',
    gap: attached ? 0 : 8,
    ...style,
  };

  const items = Children.toArray(children).filter(isValidElement);

  return (
    <div ref={ref} role="group" style={containerStyle}>
      {items.map((child, index) => {
        const isFirst = index === 0;
        const isLast = index === items.length - 1;

        const overrideProps: Partial<ButtonProps> = {};
        if (size) overrideProps.size = size;
        if (variant) overrideProps.variant = variant;

        if (attached) {
          const radiusValue = theme.radius.sm;

          let borderRadius: string;
          if (items.length === 1) {
            borderRadius = `${radiusValue}px`;
          } else if (isVertical) {
            borderRadius = isFirst
              ? `${radiusValue}px ${radiusValue}px 0 0`
              : isLast
                ? `0 0 ${radiusValue}px ${radiusValue}px`
                : '0';
          } else {
            borderRadius = isFirst
              ? `${radiusValue}px 0 0 ${radiusValue}px`
              : isLast
                ? `0 ${radiusValue}px ${radiusValue}px 0`
                : '0';
          }

          const borderStyle: CSSProperties = { borderRadius };

          if (!isFirst) {
            if (isVertical) {
              borderStyle.borderTopWidth = 0;
              borderStyle.marginTop = -1;
            } else {
              borderStyle.borderLeftWidth = 0;
              borderStyle.marginLeft = -1;
            }
          }

          overrideProps.style = {
            ...borderStyle,
            ...(child as ReactElement<ButtonProps>).props.style,
          };
        }

        return cloneElement(child as ReactElement<ButtonProps>, overrideProps);
      })}
    </div>
  );
}

import {
  useState,
  type CSSProperties,
} from 'react';
import { mergeStyles } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface CalendarProps {
  year?: number;
  month?: number;
  selected?: Date;
  outlined?: Date;
  onSelect?: (date: Date) => void;
  onClear?: () => void;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

const DAY_LABELS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

const MONTH_NAMES = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function getDaysInMonth(year: number, month: number): number {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstDayOfWeek(year: number, month: number): number {
  return new Date(year, month, 1).getDay();
}

interface DayCell {
  date: Date;
  dayOfMonth: number;
  isCurrentMonth: boolean;
}

function buildCalendarGrid(year: number, month: number): DayCell[] {
  const firstDay = getFirstDayOfWeek(year, month);
  const daysInMonth = getDaysInMonth(year, month);
  const daysInPrevMonth = getDaysInMonth(year, month - 1);

  const cells: DayCell[] = [];

  // Previous month trailing days
  for (let i = firstDay - 1; i >= 0; i--) {
    const day = daysInPrevMonth - i;
    cells.push({
      date: new Date(year, month - 1, day),
      dayOfMonth: day,
      isCurrentMonth: false,
    });
  }

  // Current month days
  for (let day = 1; day <= daysInMonth; day++) {
    cells.push({
      date: new Date(year, month, day),
      dayOfMonth: day,
      isCurrentMonth: true,
    });
  }

  // Next month leading days to fill grid
  const remaining = 7 - (cells.length % 7);
  if (remaining < 7) {
    for (let day = 1; day <= remaining; day++) {
      cells.push({
        date: new Date(year, month + 1, day),
        dayOfMonth: day,
        isCurrentMonth: false,
      });
    }
  }

  return cells;
}

export function Calendar({
  year: yearProp,
  month: monthProp,
  selected,
  outlined,
  onSelect,
  onClear,
  style,
  ref,
  ...rest
}: CalendarProps) {
  const theme = useTheme();
  const today = new Date();

  const [viewYear, setViewYear] = useState(
    yearProp ?? selected?.getFullYear() ?? today.getFullYear(),
  );
  const [viewMonth, setViewMonth] = useState(
    monthProp ?? selected?.getMonth() ?? today.getMonth(),
  );
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  const displayYear = yearProp ?? viewYear;
  const displayMonth = monthProp ?? viewMonth;

  const cells = buildCalendarGrid(displayYear, displayMonth);

  function navigateMonth(delta: number) {
    let newMonth = viewMonth + delta;
    let newYear = viewYear;
    if (newMonth < 0) {
      newMonth = 11;
      newYear -= 1;
    } else if (newMonth > 11) {
      newMonth = 0;
      newYear += 1;
    }
    setViewMonth(newMonth);
    setViewYear(newYear);
  }

  const containerStyle: CSSProperties = mergeStyles(
    {
      width: 340,
      padding: 20,
      backgroundColor: theme.semantic.surface.card,
      borderRadius: theme.radius.md,
      boxShadow: theme.shadow.card,
      boxSizing: 'border-box' as const,
      fontFamily: theme.fontFamily.sans,
    },
    style,
  );

  const headerStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 12,
  };

  const navButtonStyle: CSSProperties = {
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    padding: 4,
    fontSize: 18,
    color: theme.semantic.text.primary,
    lineHeight: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  };

  const monthYearStyle: CSSProperties = {
    ...theme.typeVariants.heading,
    color: theme.semantic.text.primary,
    textAlign: 'center' as const,
  };

  const gridStyle: CSSProperties = {
    display: 'grid',
    gridTemplateColumns: 'repeat(7, 1fr)',
    gap: 4,
  };

  const dayHeaderStyle: CSSProperties = {
    ...theme.typeVariants.label,
    color: theme.semantic.text.muted,
    textAlign: 'center' as const,
    height: 38,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  };

  function getDayCellStyle(cell: DayCell, index: number): CSSProperties {
    const isSelected = selected != null && isSameDay(cell.date, selected);
    const isOutlined = outlined != null && isSameDay(cell.date, outlined);
    const isToday = isSameDay(cell.date, today);
    const isHovered = hoveredIndex === index && !isSelected;

    const cellStyle: CSSProperties = {
      width: 38,
      height: 38,
      borderRadius: theme.radius.sm,
      fontFamily: theme.fontFamily.sans,
      fontSize: theme.fontSize[14],
      fontWeight: isToday
        ? theme.fontWeight.bold
        : theme.fontWeight.medium,
      color: isSelected
        ? theme.semantic.text.inverse
        : cell.isCurrentMonth
          ? theme.semantic.text.primary
          : theme.semantic.text.muted,
      backgroundColor: isSelected
        ? theme.semantic.fill.primary
        : isHovered
          ? theme.semantic.surface.hover
          : 'transparent',
      border: isOutlined && !isSelected
        ? `2px solid ${theme.semantic.border.focus}`
        : '2px solid transparent',
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 0,
      lineHeight: 1,
      boxSizing: 'border-box' as const,
    };

    return cellStyle;
  }

  const footerStyle: CSSProperties = {
    borderTop: `1px solid ${theme.semantic.border.subtle}`,
    paddingTop: 8,
    marginTop: 8,
    display: 'flex',
    justifyContent: 'flex-end',
  };

  const clearButtonStyle: CSSProperties = {
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    color: theme.semantic.text.link,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.medium,
    padding: 0,
  };

  return (
    <div ref={ref} style={containerStyle} {...rest}>
      {/* Header */}
      <div style={headerStyle}>
        <button
          type="button"
          style={navButtonStyle}
          onClick={() => navigateMonth(-1)}
          aria-label="Previous month"
        >
          &#8249;
        </button>
        <span style={monthYearStyle}>
          {MONTH_NAMES[displayMonth]} {displayYear}
        </span>
        <button
          type="button"
          style={navButtonStyle}
          onClick={() => navigateMonth(1)}
          aria-label="Next month"
        >
          &#8250;
        </button>
      </div>

      {/* Grid */}
      <div style={gridStyle} role="grid" aria-label="Calendar">
        {/* Day-of-week headers */}
        {DAY_LABELS.map((label, i) => (
          <div key={`header-${i}`} style={dayHeaderStyle} role="columnheader">
            {label}
          </div>
        ))}

        {/* Day cells */}
        {cells.map((cell, i) => (
          <button
            key={`day-${i}`}
            type="button"
            style={getDayCellStyle(cell, i)}
            onMouseEnter={() => setHoveredIndex(i)}
            onMouseLeave={() => setHoveredIndex(null)}
            onClick={() => onSelect?.(cell.date)}
            aria-label={cell.date.toDateString()}
            aria-selected={
              selected != null ? isSameDay(cell.date, selected) : undefined
            }
          >
            {cell.dayOfMonth}
          </button>
        ))}
      </div>

      {/* Footer */}
      {onClear != null && (
        <div style={footerStyle}>
          <button
            type="button"
            style={clearButtonStyle}
            onClick={onClear}
          >
            Clear
          </button>
        </div>
      )}
    </div>
  );
}

import { type ElementType, type CSSProperties, type ReactNode } from 'react';
import { useTheme } from 'jind-ui-kit';

export interface CardOwnProps {
  as?: ElementType;
  padding?: number;
  title?: string;
  actions?: ReactNode;
  children?: ReactNode;
  style?: CSSProperties;
  ref?: React.Ref<HTMLElement>;
}

export type CardProps<E extends ElementType = 'div'> = CardOwnProps &
  Omit<React.ComponentPropsWithoutRef<E>, keyof CardOwnProps>;

export function Card({
  as: Component = 'div',
  padding = 20,
  title,
  actions,
  children,
  style,
  ref,
  ...rest
}: CardProps) {
  const theme = useTheme();

  const cardStyle: CSSProperties = {
    background: theme.semantic.surface.card,
    borderRadius: theme.radius.md,
    boxShadow: theme.shadow.card,
    boxSizing: 'border-box',
    padding,
    ...style,
  };

  const headerStyle: CSSProperties = {
    display: 'flex',
