import {
  useState,
  useRef,
  useCallback,
  useEffect,
  Children,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface CarouselProps {
  children: ReactNode;
  autoPlay?: boolean;
  interval?: number;
  showDots?: boolean;
  showArrows?: boolean;
  loop?: boolean;
  slidesToShow?: number;
  gap?: number;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function Carousel({
  children,
  autoPlay = false,
  interval = 4000,
  showDots = true,
  showArrows = true,
  loop = false,
  slidesToShow = 1,
  gap = 16,
  style,
  ref,
}: CarouselProps) {
  const theme = useTheme();
  const items = Children.toArray(children);
  const total = items.length;
  const [current, setCurrent] = useState(0);
  const trackRef = useRef<HTMLDivElement>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | undefined>(undefined);

  const maxIndex = Math.max(0, total - slidesToShow);

  const goTo = useCallback(
    (index: number) => {
      if (loop) {
        setCurrent(((index % total) + total) % total);
      } else {
        setCurrent(Math.max(0, Math.min(index, maxIndex)));
      }
    },
    [loop, total, maxIndex],
  );

  const next = useCallback(() => goTo(current + 1), [current, goTo]);
  const prev = useCallback(() => goTo(current - 1), [current, goTo]);

  useEffect(() => {
    if (!autoPlay) return;
    timerRef.current = setInterval(next, interval);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [autoPlay, interval, next]);

  const canPrev = loop || current > 0;
  const canNext = loop || current < maxIndex;

  const transitionValue = transition('background-color', 'opacity');

  const containerStyle: CSSProperties = mergeStyles(
    {
      position: 'relative',
      width: '100%',
      overflow: 'hidden',
    },
    style,
  );

  const trackStyle: CSSProperties = {
    display: 'flex',
    gap,
    transition: 'transform 300ms cubic-bezier(0.4, 0, 0.2, 1)',
    transform: `translateX(calc(-${current} * (100% / ${slidesToShow} + ${gap}px)))`,
  };

  const slideStyle: CSSProperties = {
    flex: `0 0 calc((100% - ${gap * (slidesToShow - 1)}px) / ${slidesToShow})`,
    minWidth: 0,
  };

  const arrowBase: CSSProperties = {
    position: 'absolute',
    top: '50%',
    transform: 'translateY(-50%)',
    zIndex: 2,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 36,
    height: 36,
    borderRadius: '50%',
    border: `1px solid ${theme.semantic.border.subtle}`,
    backgroundColor: theme.semantic.surface.card,
    boxShadow: theme.shadow.sm,
    cursor: 'pointer',
    fontSize: 18,
    color: theme.semantic.text.primary,
    transition: transitionValue,
    outline: 'none',
    padding: 0,
  };

  const dotsStyle: CSSProperties = {
    display: 'flex',
    justifyContent: 'center',
    gap: 8,
    marginTop: 12,
  };

  return (
    <div ref={ref} style={containerStyle}>
      <div ref={trackRef} style={trackStyle}>
        {items.map((child, i) => (
          <div key={i} style={slideStyle} aria-roledescription="slide" aria-label={`Slide ${i + 1} of ${total}`}>
            {child}
          </div>
        ))}
      </div>

      {showArrows && total > slidesToShow && (
        <>
          <button
            type="button"
            style={{
              ...arrowBase,
              left: 8,
              opacity: canPrev ? 1 : 0.3,
              pointerEvents: canPrev ? 'auto' : 'none',
            }}
            onClick={prev}
            aria-label="Previous slide"
            disabled={!canPrev}
          >
            {'←'}
          </button>
          <button
            type="button"
            style={{
              ...arrowBase,
              right: 8,
              opacity: canNext ? 1 : 0.3,
              pointerEvents: canNext ? 'auto' : 'none',
            }}
            onClick={next}
            aria-label="Next slide"
            disabled={!canNext}
          >
            {'→'}
          </button>
        </>
      )}

      {showDots && total > slidesToShow && (
        <div style={dotsStyle} role="tablist" aria-label="Slides">
          {Array.from({ length: maxIndex + 1 }, (_, i) => (
            <button
              key={i}
              type="button"
              role="tab"
              aria-selected={i === current}
              aria-label={`Go to slide ${i + 1}`}
              onClick={() => goTo(i)}
              style={{
                width: i === current ? 20 : 8,
                height: 8,
                borderRadius: 4,
                border: 'none',
                padding: 0,
                cursor: 'pointer',
                backgroundColor: i === current
                  ? theme.semantic.fill.primary
                  : theme.semantic.border.default,
                transition: 'width 200ms ease, background-color 200ms ease',
                outline: 'none',
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

import {
  useRef,
  useState,
  type CSSProperties,
} from 'react';
import { useControllableState, useTheme } from 'jind-ui-kit';

export interface CheckboxProps {
  checked?: boolean;
  defaultChecked?: boolean;
  disabled?: boolean;
  onChange?: (checked: boolean) => void;
  label?: string;
  indeterminate?: boolean;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function Checkbox({
  checked: checkedProp,
  defaultChecked = false,
  disabled = false,
  onChange,
  label,
  indeterminate = false,
  style,
  ref,
  ...rest
}: CheckboxProps) {
  const theme = useTheme();
  const [checked, setChecked] = useControllableState(checkedProp, defaultChecked, onChange);
  const [focused, setFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const isCheckedOrIndeterminate = checked || indeterminate;

  const containerStyle: CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    gap: 8,
    cursor: disabled ? 'default' : 'pointer',
    opacity: disabled ? 0.5 : 1,
    pointerEvents: disabled ? 'none' : undefined,
    ...style,
  };

  const boxStyle: CSSProperties = {
    width: 16,
    height: 16,
    borderRadius: theme.radius.xs,
    border: `1.5px solid ${isCheckedOrIndeterminate ? theme.semantic.fill.primary : theme.semantic.border.default}`,
    background: isCheckedOrIndeterminate ? theme.semantic.fill.primary : theme.semantic.surface.card,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
    boxSizing: 'border-box' as const,
    transition: `background ${theme.duration.fast}ms ${theme.easing.standard}, border-color ${theme.duration.fast}ms ${theme.easing.standard}`,
    ...(focused && {
      boxShadow: theme.focusRing.primary,
    }),
  };

  const iconStyle: CSSProperties = {
    color: theme.semantic.text.inverse,
    fontSize: 10,
    lineHeight: 1,
    fontWeight: theme.fontWeight.bold,
  };

  const labelStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    lineHeight: theme.lineHeight.normal,
    color: theme.semantic.text.primary,
    userSelect: 'none',
  };

  const hiddenInputStyle: CSSProperties = {
    position: 'absolute',
    opacity: 0,
    width: 0,
    height: 0,
    margin: 0,
    padding: 0,
    overflow: 'hidden',
  };

  const handleClick = () => {
    if (!disabled) {
      setChecked(!checked);
      inputRef.current?.focus();
    }
  };

  return (
    <div
      ref={ref}
      style={containerStyle}
      onClick={handleClick}
      role="presentation"
      {...rest}
    >
      <div style={boxStyle}>
        <span style={{
          ...iconStyle,
          visibility: isCheckedOrIndeterminate ? 'visible' : 'hidden',
        }}>
          {indeterminate ? '—' : '✓'}
        </span>
      </div>
      <input
        ref={inputRef}
        type="checkbox"
        checked={checked}
        disabled={disabled}
        onChange={(e) => setChecked(e.target.checked)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        style={hiddenInputStyle}
        aria-checked={indeterminate ? 'mixed' : checked}
        tabIndex={0}
      />
      {label && <span style={labelStyle}>{label}</span>}
    </div>
  );
}

import { type CSSProperties, type ReactNode } from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface ChipProps {
  icon?: string;
  selected?: boolean;
  disabled?: boolean;
  onClick?: () => void;
  children: ReactNode;
  style?: CSSProperties;
}

export function Chip({
  icon,
  selected = false,
  disabled = false,
  onClick,
  children,
  style,
}: ChipProps) {
  const theme = useTheme();

  const textColor = selected
    ? theme.colors.blue[500]
    : theme.semantic.text.primary;

  const chipStyle: CSSProperties = mergeStyles(
    {
      display: 'inline-flex',
      alignItems: 'center',
      gap: 8,
      height: 40,
      padding: '0 14px',
      borderRadius: theme.radius.sm,
      fontFamily: theme.typeVariants.control.fontFamily,
      fontSize: theme.typeVariants.control.fontSize,
      fontWeight: theme.typeVariants.control.fontWeight,
      lineHeight: theme.typeVariants.control.lineHeight,
      cursor: disabled ? 'default' : 'pointer',
      outline: 'none',
      boxSizing: 'border-box',
      background: selected ? theme.colors.blue[50] : theme.semantic.surface.card,
      color: textColor,
      border: `1px solid ${selected ? theme.colors.blue[500] : theme.semantic.border.subtle}`,
      boxShadow: selected ? undefined : theme.shadow.xs,
      opacity: disabled ? 0.5 : 1,
      pointerEvents: disabled ? 'none' : undefined,
      transition: transition('background-color', 'border-color', 'color', 'box-shadow'),
    },
    style,
  );

  return (
    <button
      type="button"
      style={chipStyle}
      disabled={disabled}
      onClick={onClick}
    >
      {icon && (
        <i
          className={`iconoir-${icon}`}
          style={{ fontSize: 18, color: textColor }}
          aria-hidden="true"
        />
      )}
      {children}
    </button>
  );
}

import {
  useRef,
  useEffect,
  useId,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from 'react';
import { transition } from 'jind-ui-kit/styles';
import { useControllableState } from 'jind-ui-kit';

export interface CollapsibleProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
  trigger: ReactNode;
  disabled?: boolean;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

export function Collapsible({
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  children,
  trigger,
  disabled = false,
  style,
  ref,
}: CollapsibleProps) {
  const [isOpen, setIsOpen] = useControllableState(controlledOpen, defaultOpen, onOpenChange);
  const contentRef = useRef<HTMLDivElement>(null);
  const contentId = useId();

  const handleToggle = () => {
    if (disabled) return;
    setIsOpen(!isOpen);
  };

  useEffect(() => {
    const el = contentRef.current;
    if (!el) return;

    if (isOpen) {
      el.style.maxHeight = `${el.scrollHeight}px`;
    } else {
      el.style.maxHeight = '0px';
    }
  }, [isOpen]);

  const containerStyle: CSSProperties = {
    ...style,
  };

  const triggerWrapperStyle: CSSProperties = {
    cursor: disabled ? 'not-allowed' : 'pointer',
    opacity: disabled ? 0.5 : 1,
    display: 'contents',
  };

  const contentStyle: CSSProperties = {
    overflow: 'hidden',
    maxHeight: isOpen ? undefined : 0,
    transition: transition('max-height'),
  };

  return (
    <div ref={ref} style={containerStyle}>
      <div
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-expanded={isOpen}
        aria-controls={contentId}
        aria-disabled={disabled}
        onClick={handleToggle}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleToggle();
          }
        }}
        style={triggerWrapperStyle}
      >
        {trigger}
      </div>
      <div
        id={contentId}
        ref={contentRef}
        role="region"
        style={contentStyle}
      >
        {children}
      </div>
    </div>
  );
}

import { useState, useRef, useCallback, type CSSProperties } from 'react';
import { transition } from 'jind-ui-kit/styles';
import { useClickOutside, useControllableState, useTheme } from 'jind-ui-kit';

export interface ComboboxOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  emptyMessage?: string;
  label?: string;
  error?: string;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function Combobox({
  options,
  value,
  defaultValue,
  onChange,
  placeholder = 'Search...',
  disabled = false,
  size = 'md',
  emptyMessage = 'No results',
  label,
  error,
  style,
  ref,
}: ComboboxProps) {
  const theme = useTheme();
  const [val, setVal] = useControllableState(value, defaultValue ?? '', onChange);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [highlightIndex, setHighlightIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useClickOutside(containerRef, () => {
    setOpen(false);
    // Reset query to selected label when closing
    const selected = options.find((o) => o.value === val);
    setQuery(selected ? selected.label : '');
  }, open);

  const filtered = options.filter(
    (opt) => opt.label.toLowerCase().includes(query.toLowerCase()),
  );

  const selectedOption = options.find((o) => o.value === val);

  const handleSelect = useCallback(
    (opt: ComboboxOption) => {
      if (opt.disabled) return;
      setVal(opt.value);
      setQuery(opt.label);
      setOpen(false);
      setHighlightIndex(-1);
    },
    [setVal],
  );

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!open) {
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        setOpen(true);
        e.preventDefault();
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setHighlightIndex((prev) => {
          const next = prev + 1;
          return next >= filtered.length ? 0 : next;
        });
        break;
      case 'ArrowUp':
        e.preventDefault();
        setHighlightIndex((prev) => {
          const next = prev - 1;
          return next < 0 ? filtered.length - 1 : next;
        });
        break;
      case 'Enter':
        e.preventDefault();
        if (highlightIndex >= 0 && highlightIndex < filtered.length) {
          handleSelect(filtered[highlightIndex]);
        }
        break;
      case 'Escape':
        e.preventDefault();
        setOpen(false);
        setQuery(selectedOption ? selectedOption.label : '');
        setHighlightIndex(-1);
        break;
    }
  };

  const height = theme.controlHeight[size];

  const wrapperStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: theme.space[4],
    ...style,
  };

  const labelStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.medium,
    color: theme.semantic.text.primary,
  };

  const fieldShell: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    width: '100%',
    height,
    padding: `0 ${theme.controlPadding.field}px`,
    borderRadius: theme.radius.md,
    background: disabled
      ? theme.semantic.surface.subtle
      : open
        ? theme.semantic.surface.card
        : theme.semantic.surface.subtle,
    border: error
      ? `2px solid ${theme.colors.red[500]}`
      : open
        ? `2px solid ${theme.semantic.border.focus}`
        : `1px solid ${theme.semantic.border.default}`,
    boxShadow: error
      ? theme.focusRing.danger
      : open
        ? theme.focusRing.primary
        : theme.shadow.xs,
    color: disabled ? theme.semantic.text.muted : theme.semantic.text.primary,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    lineHeight: theme.lineHeight.normal,
    transition: transition('background-color', 'border-color', 'box-shadow'),
    opacity: disabled ? 0.5 : 1,
    cursor: disabled ? 'not-allowed' : 'text',
    boxSizing: 'border-box',
  };

  const inputStyle: CSSProperties = {
    flex: 1,
    border: 'none',
    outline: 'none',
    background: 'transparent',
    color: 'inherit',
    font: 'inherit',
    padding: 0,
    width: '100%',
    cursor: 'inherit',
  };

  const chevronStyle: CSSProperties = {
    fontSize: 10,
    color: theme.semantic.text.muted,
    transform: `rotate(${open ? 180 : 0}deg)`,
    transition: transition('transform'),
    flexShrink: 0,
    marginLeft: theme.space[4],
    pointerEvents: 'none',
  };

  const dropdownStyle: CSSProperties = {
    position: 'absolute',
    top: 'calc(100% + 6px)',
    left: 0,
    right: 0,
    borderRadius: theme.radius.md,
    background: theme.semantic.surface.card,
    boxShadow: theme.shadow.menu,
    border: `1px solid ${theme.semantic.border.default}`,
    zIndex: 1000,
    overflowY: 'auto',
    maxHeight: 240,
    padding: `${theme.space[2]}px 0`,
  };

  const emptyStyle: CSSProperties = {
    padding: `${theme.space[4]}px ${theme.space[6]}px`,
    color: theme.semantic.text.muted,
    fontSize: theme.fontSize[14],
    fontFamily: theme.fontFamily.sans,
  };

  const errorStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[12],
    color: theme.semantic.text.danger,
    marginTop: theme.space[2],
  };

  return (
    <div ref={ref} style={wrapperStyle}>
      {label && <label style={labelStyle}>{label}</label>}
      <div
        ref={containerRef}
        style={{ position: 'relative', width: '100%' }}
      >
        <div style={fieldShell}>
          <input
            ref={inputRef}
            style={inputStyle}
            value={open ? query : (selectedOption ? selectedOption.label : query)}
            placeholder={placeholder}
            disabled={disabled}
            data-testid="combobox-input"
            onChange={(e) => {
              setQuery(e.target.value);
              setHighlightIndex(-1);
              if (!open) setOpen(true);
            }}
            onFocus={() => {
              if (!disabled) {
                setOpen(true);
                setQuery(selectedOption ? selectedOption.label : '');
              }
            }}
            onKeyDown={handleKeyDown}
          />
          <span style={chevronStyle}>&#x25BC;</span>
        </div>

        {open && (
          <div style={dropdownStyle} data-testid="combobox-dropdown">
            {filtered.length === 0 ? (
              <div style={emptyStyle}>{emptyMessage}</div>
            ) : (
              filtered.map((opt, idx) => {
                const isSelected = opt.value === val;
                const isHighlighted = idx === highlightIndex;

                const optionStyle: CSSProperties = {
                  display: 'flex',
                  alignItems: 'center',
                  padding: `${theme.space[4]}px ${theme.space[6]}px`,
                  cursor: opt.disabled ? 'not-allowed' : 'pointer',
                  background: isHighlighted
                    ? theme.semantic.surface.hover
                    : isSelected
                      ? theme.semantic.surface.selected
                      : 'transparent',
                  fontSize: theme.fontSize[14],
                  fontFamily: theme.fontFamily.sans,
                  color: opt.disabled
                    ? theme.semantic.text.muted
                    : theme.semantic.text.primary,
                  opacity: opt.disabled ? 0.5 : 1,
                };

                return (
                  <div
                    key={opt.value}
                    role="option"
                    data-testid="combobox-option"
                    style={optionStyle}
                    onMouseEnter={(e) => {
                      if (!opt.disabled) {
                        setHighlightIndex(idx);
                        (e.currentTarget as HTMLElement).style.background =
                          theme.semantic.surface.hover;
                      }
                    }}
                    onMouseLeave={(e) => {
                      setHighlightIndex(-1);
                      (e.currentTarget as HTMLElement).style.background =
                        isSelected ? theme.semantic.surface.selected : 'transparent';
                    }}
                    onClick={() => handleSelect(opt)}
                  >
                    <span style={{ flex: 1 }}>{opt.label}</span>
                    {isSelected && (
                      <span style={{ color: theme.semantic.fill.primary, flexShrink: 0 }}>
                        &#x2713;
                      </span>
                    )}
                  </div>
                );
              })
            )}
          </div>
        )}
      </div>
      {error && <span style={errorStyle}>{error}</span>}
    </div>
  );
}

import {
  useState,
  useEffect,
  useRef,
  useCallback,
  type CSSProperties,
  type ReactNode,
  type KeyboardEvent,
} from 'react';
import { Portal, useTheme } from 'jind-ui-kit';
import { mergeStyles, transition } from 'jind-ui-kit/styles';

export interface CommandItem {
  id: string;
  label: string;
  icon?: string;
  description?: string;
  group?: string;
  shortcut?: string;
  onSelect: () => void;
  disabled?: boolean;
}

export interface CommandMenuProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  placeholder?: string;
  emptyMessage?: string;
  footer?: ReactNode;
  style?: CSSProperties;
}

export function CommandMenu({
  open,
  onOpenChange,
  items,
  placeholder = 'Search commands...',
  emptyMessage = 'No results found.',
  footer,
  style,
}: CommandMenuProps) {
  const theme = useTheme();
  const [query, setQuery] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  const filtered = items.filter((item) => {
    if (!query) return true;
    const q = query.toLowerCase();
    return (
      item.label.toLowerCase().includes(q) ||
      item.description?.toLowerCase().includes(q) ||
      item.group?.toLowerCase().includes(q)
    );
  });

  const groups = new Map<string, CommandItem[]>();
  for (const item of filtered) {
    const key = item.group ?? '';
    const existing = groups.get(key);
    if (existing) {
      existing.push(item);
    } else {
      groups.set(key, [item]);
    }
  }

  const flatItems = filtered.filter((i) => !i.disabled);

  useEffect(() => {
    if (open) {
      setQuery('');
      setActiveIndex(0);
      setTimeout(() => inputRef.current?.focus(), 0);
    }
  }, [open]);

  useEffect(() => {
    setActiveIndex(0);
  }, [query]);

  useEffect(() => {
    if (!open) return;
    function handleGlobalKey(e: globalThis.KeyboardEvent) {
      if (e.key === 'Escape') {
        e.preventDefault();
        onOpenChange(false);
      }
    }
    document.addEventListener('keydown', handleGlobalKey);
    return () => document.removeEventListener('keydown', handleGlobalKey);
  }, [open, onOpenChange]);

  const scrollActiveIntoView = useCallback(
    (index: number) => {
      const list = listRef.current;
      if (!list) return;
      const el = list.children[index] as HTMLElement | undefined;
      el?.scrollIntoView({ block: 'nearest' });
    },
    [],
  );

  function handleKeyDown(e: KeyboardEvent) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      const next = Math.min(activeIndex + 1, flatItems.length - 1);
      setActiveIndex(next);
      scrollActiveIntoView(next);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      const prev = Math.max(activeIndex - 1, 0);
      setActiveIndex(prev);
      scrollActiveIntoView(prev);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const item = flatItems[activeIndex];
      if (item) {
        item.onSelect();
        onOpenChange(false);
      }
    }
  }

  function handleBackdropClick() {
    onOpenChange(false);
  }

  if (!open) return null;

  const transitionValue = transition('background-color');

  const overlayStyle: CSSProperties = {
    position: 'fixed',
    inset: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.4)',
    display: 'flex',
    alignItems: 'flex-start',
    justifyContent: 'center',
    paddingTop: '15vh',
    zIndex: 9999,
  };

  const panelStyle: CSSProperties = mergeStyles(
    {
      width: '100%',
      maxWidth: 540,
      maxHeight: '60vh',
      display: 'flex',
      flexDirection: 'column',
      backgroundColor: theme.semantic.surface.card,
      borderRadius: theme.radius.md,
      boxShadow: theme.shadow.menu,
      border: `1px solid ${theme.semantic.border.subtle}`,
      overflow: 'hidden',
    },
    style,
  );

  const inputStyle: CSSProperties = {
    width: '100%',
    padding: '14px 16px',
    border: 'none',
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    backgroundColor: 'transparent',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[15],
    color: theme.semantic.text.primary,
    outline: 'none',
    boxSizing: 'border-box',
  };

  const groupLabelStyle: CSSProperties = {
    padding: '8px 16px 4px',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[11],
    fontWeight: theme.fontWeight.semibold,
    color: theme.semantic.text.muted,
    textTransform: 'uppercase',
    letterSpacing: 0.5,
  };

  const emptyStyle: CSSProperties = {
    padding: '24px 16px',
    textAlign: 'center',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    color: theme.semantic.text.muted,
  };

  const footerStyle: CSSProperties = {
    padding: '8px 16px',
    borderTop: `1px solid ${theme.semantic.border.subtle}`,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[12],
    color: theme.semantic.text.muted,
    display: 'flex',
    gap: 16,
  };

  let flatIndex = -1;

  return (
    <Portal>
      <div style={overlayStyle} onClick={handleBackdropClick}>
        <div
          role="dialog"
          aria-label="Command menu"
          style={panelStyle}
          onClick={(e) => e.stopPropagation()}
          onKeyDown={handleKeyDown}
        >
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            style={inputStyle}
            aria-label="Search commands"
            autoComplete="off"
          />

          <div
            ref={listRef}
            role="listbox"
            style={{ overflowY: 'auto', flex: 1, padding: '4px 0' }}
          >
            {filtered.length === 0 && (
              <div style={emptyStyle}>{emptyMessage}</div>
            )}

            {Array.from(groups.entries()).map(([group, groupItems]) => (
              <div key={group || '__ungrouped'}>
                {group && <div style={groupLabelStyle}>{group}</div>}
                {groupItems.map((item) => {
                  if (!item.disabled) flatIndex++;
                  const isActive = !item.disabled && flatIndex === activeIndex;

                  const itemStyle: CSSProperties = {
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '10px 16px',
                    cursor: item.disabled ? 'not-allowed' : 'pointer',
                    backgroundColor: isActive
                      ? theme.semantic.surface.hover
                      : 'transparent',
                    opacity: item.disabled ? 0.5 : 1,
                    transition: transitionValue,
                    border: 'none',
                    width: '100%',
                    textAlign: 'left',
                    fontFamily: theme.fontFamily.sans,
                    outline: 'none',
                  };

                  return (
                    <div
                      key={item.id}
                      role="option"
                      aria-selected={isActive}
                      aria-disabled={item.disabled || undefined}
                      style={itemStyle}
                      onClick={() => {
                        if (item.disabled) return;
                        item.onSelect();
                        onOpenChange(false);
                      }}
                      onMouseEnter={() => {
                        if (!item.disabled) {
                          const idx = flatItems.indexOf(item);
                          if (idx >= 0) setActiveIndex(idx);
                        }
                      }}
                    >
                      {item.icon && (
                        <i
                          className={`iconoir-${item.icon}`}
                          style={{
                            fontSize: 18,
                            color: theme.semantic.icon.muted,
                          }}
                          aria-hidden="true"
                        />
                      )}
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div
                          style={{
                            fontSize: theme.fontSize[14],
                            fontWeight: theme.fontWeight.medium,
                            color: theme.semantic.text.primary,
                          }}
                        >
                          {item.label}
                        </div>
                        {item.description && (
                          <div
                            style={{
                              fontSize: theme.fontSize[12],
                              color: theme.semantic.text.muted,
                              marginTop: 1,
                            }}
                          >
                            {item.description}
                          </div>
                        )}
                      </div>
                      {item.shortcut && (
                        <kbd
                          style={{
                            fontSize: theme.fontSize[11],
                            fontFamily: theme.fontFamily.mono,
                            color: theme.semantic.text.muted,
                            padding: '2px 6px',
                            borderRadius: theme.radius.xs,
                            border: `1px solid ${theme.semantic.border.subtle}`,
                            backgroundColor: theme.semantic.surface.subtle,
                          }}
                        >
                          {item.shortcut}
                        </kbd>
                      )}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>

          {footer && <div style={footerStyle}>{footer}</div>}
        </div>
      </div>
    </Portal>
  );
}

import {
  useState,
  useRef,
  useCallback,
  useEffect,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { Portal, useClickOutside, useTheme } from 'jind-ui-kit';

export interface ContextMenuItem {
  label: string;
  icon?: string;
  shortcut?: string;
  onSelect?: () => void;
  disabled?: boolean;
  danger?: boolean;
  separator?: boolean;
}

export interface ContextMenuProps {
  items: ContextMenuItem[];
  children: ReactNode;
  disabled?: boolean;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

function ContextMenuItemRow({
  item,
  onClose,
}: {
  item: ContextMenuItem;
  onClose: () => void;
}) {
  const theme = useTheme();
  const [hovered, setHovered] = useState(false);

  const itemStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: theme.space[4],
    padding: `${theme.space[3]}px ${theme.space[6]}px`,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    color: item.danger ? theme.semantic.text.danger : theme.semantic.text.primary,
    background: hovered && !item.disabled ? theme.semantic.surface.hover : 'transparent',
    borderRadius: theme.radius.sm,
    cursor: item.disabled ? 'default' : 'pointer',
    opacity: item.disabled ? 0.5 : 1,
    pointerEvents: item.disabled ? 'none' : undefined,
    transition: transition('background-color'),
    boxSizing: 'border-box',
    border: 'none',
    width: '100%',
    textAlign: 'left',
  };

  const shortcutStyle: CSSProperties = {
    marginLeft: 'auto',
    color: theme.semantic.text.muted,
    fontSize: theme.fontSize[12],
    fontFamily: theme.fontFamily.mono,
    flexShrink: 0,
  };

  function handleClick() {
    if (!item.disabled) {
      item.onSelect?.();
      onClose();
    }
  }

  return (
    <div
      style={itemStyle}
      role="menuitem"
      aria-disabled={item.disabled || undefined}
      onMouseEnter={() => !item.disabled && setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={handleClick}
    >
      {item.icon && (
        <i
          className={`iconoir-${item.icon}`}
          style={{ fontSize: 16, flexShrink: 0 }}
          aria-hidden="true"
        />
      )}
      <span style={{ flex: 1, minWidth: 0 }}>{item.label}</span>
      {item.shortcut && <span style={shortcutStyle}>{item.shortcut}</span>}
    </div>
  );
}

export function ContextMenu({
  items,
  children,
  disabled = false,
  style,
  ref,
}: ContextMenuProps) {
  const theme = useTheme();
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const menuRef = useRef<HTMLDivElement>(null);

  useClickOutside(menuRef, () => setOpen(false), open);

  const handleClose = useCallback(() => {
    setOpen(false);
  }, []);

  useEffect(() => {
    if (!open) return;

    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') {
        setOpen(false);
      }
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [open]);

  function handleContextMenu(e: React.MouseEvent) {
    if (disabled) return;
    e.preventDefault();
    setPosition({ x: e.clientX, y: e.clientY });
    setOpen(true);
  }

  const menuStyle: CSSProperties = {
    position: 'fixed',
    top: position.y,
    left: position.x,
    zIndex: 1100,
    background: theme.semantic.surface.card,
    border: `1px solid ${theme.semantic.border.default}`,
    boxShadow: theme.shadow.menu,
    borderRadius: theme.radius.md,
    paddingTop: theme.space[2],
    paddingBottom: theme.space[2],
    minWidth: 180,
    boxSizing: 'border-box',
  };

  const separatorStyle: CSSProperties = {
    height: 0,
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    marginTop: theme.space[2],
    marginBottom: theme.space[2],
  };

  return (
    <div ref={ref} style={mergeStyles({ display: 'contents' }, style)} onContextMenu={handleContextMenu}>
      {children}
      {open && (
        <Portal>
          <div ref={menuRef} style={menuStyle} role="menu">
            {items.map((item, index) => {
              if (item.separator) {
                return <div key={index} style={separatorStyle} aria-hidden="true" />;
              }
              return (
                <ContextMenuItemRow key={index} item={item} onClose={handleClose} />
              );
            })}
          </div>
        </Portal>
      )}
    </div>
  );
}

import {
  useMemo,
  useState,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

/* ─── Types ─── */

export interface DataColumn<T> {
  key: string;
  header: string;
  sortable?: boolean;
  render?: (value: unknown, row: T) => ReactNode;
  width?: number | string;
  align?: 'left' | 'center' | 'right';
}

export interface DataTableProps<T extends Record<string, unknown>> {
  columns: DataColumn<T>[];
  data: T[];
  sortable?: boolean;
  filterable?: boolean;
  paginated?: boolean;
  pageSize?: number;
  emptyMessage?: string;
  onRowClick?: (row: T) => void;
  selectable?: boolean;
  selectedRows?: T[];
  onSelectionChange?: (rows: T[]) => void;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

/* ─── Helpers ─── */

type SortDirection = 'asc' | 'desc' | null;

function getCellValue<T extends Record<string, unknown>>(
  row: T,
  key: string,
): unknown {
  return row[key];
}

function compareValues(a: unknown, b: unknown, dir: 'asc' | 'desc'): number {
  const multiplier = dir === 'asc' ? 1 : -1;

  if (a == null && b == null) return 0;
  if (a == null) return 1 * multiplier;
  if (b == null) return -1 * multiplier;

  if (typeof a === 'number' && typeof b === 'number') {
    return (a - b) * multiplier;
  }

  return String(a).localeCompare(String(b)) * multiplier;
}

function matchesFilter<T extends Record<string, unknown>>(
  row: T,
  filter: string,
  columns: DataColumn<T>[],
): boolean {
  const lowerFilter = filter.toLowerCase();
  return columns.some((col) => {
    const value = getCellValue(row, col.key);
    if (value == null) return false;
    return String(value).toLowerCase().includes(lowerFilter);
  });
}

/* ─── DataTable ─── */

export function DataTable<T extends Record<string, unknown>>({
  columns,
  data,
  sortable = false,
  filterable = false,
  paginated = false,
  pageSize = 10,
  emptyMessage = 'No data',
  onRowClick,
  selectable = false,
  selectedRows,
  onSelectionChange,
  style,
  ref,
}: DataTableProps<T>) {
  const theme = useTheme();

  // Internal state
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<SortDirection>(null);
  const [filter, setFilter] = useState('');
  const [page, setPage] = useState(1);
  const [internalSelection, setInternalSelection] = useState<T[]>([]);

  const selection = selectedRows ?? internalSelection;
  const setSelection = (rows: T[]) => {
    if (onSelectionChange) {
      onSelectionChange(rows);
    } else {
      setInternalSelection(rows);
    }
  };

  // Filter data
  const filteredData = useMemo(() => {
    if (!filter) return data;
    return data.filter((row) => matchesFilter(row, filter, columns));
  }, [data, filter, columns]);

  // Sort data
  const sortedData = useMemo(() => {
    if (!sortKey || !sortDir) return filteredData;
    return [...filteredData].sort((a, b) =>
      compareValues(getCellValue(a, sortKey), getCellValue(b, sortKey), sortDir),
    );
  }, [filteredData, sortKey, sortDir]);

  // Paginate
  const totalItems = sortedData.length;
  const totalPages = paginated ? Math.max(1, Math.ceil(totalItems / pageSize)) : 1;
  const safePage = Math.min(page, totalPages);
  const displayedData = paginated
    ? sortedData.slice((safePage - 1) * pageSize, safePage * pageSize)
    : sortedData;

  const startItem = totalItems === 0 ? 0 : (safePage - 1) * pageSize + 1;
  const endItem = Math.min(safePage * pageSize, totalItems);

  // Sort handler
  const handleSort = (key: string) => {
    if (sortKey === key) {
      if (sortDir === 'asc') {
        setSortDir('desc');
      } else if (sortDir === 'desc') {
        setSortKey(null);
        setSortDir(null);
      }
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
    setPage(1);
  };

  // Selection helpers
  const isRowSelected = (row: T) => selection.includes(row);
  const allSelected =
    displayedData.length > 0 &&
    displayedData.every((row) => selection.includes(row));
  const someSelected =
    !allSelected && displayedData.some((row) => selection.includes(row));

  const toggleRow = (row: T) => {
    if (isRowSelected(row)) {
      setSelection(selection.filter((r) => r !== row));
    } else {
      setSelection([...selection, row]);
    }
  };

  const toggleAll = () => {
    if (allSelected) {
      setSelection(selection.filter((r) => !displayedData.includes(r)));
    } else {
      const newSelection = [...selection];
      for (const row of displayedData) {
        if (!newSelection.includes(row)) {
          newSelection.push(row);
        }
      }
      setSelection(newSelection);
    }
  };

  // ─── Styles ───

  const wrapperStyle: CSSProperties = mergeStyles(
    {
      borderRadius: theme.radius.md,
      overflow: 'hidden',
      border: `1px solid ${theme.semantic.border.default}`,
      background: theme.semantic.surface.card,
    },
    style,
  );

  const filterStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    padding: `${theme.space[6]}px ${theme.space[7]}px`,
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
  };

  const filterInputStyle: CSSProperties = {
    width: '100%',
    maxWidth: 320,
    height: theme.controlHeight.sm,
    padding: `0 ${theme.controlPadding.field}px`,
    border: `1px solid ${theme.semantic.border.default}`,
    borderRadius: theme.radius.md,
    background: theme.semantic.surface.card,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    color: theme.semantic.text.primary,
    outline: 'none',
    boxSizing: 'border-box',
    transition: transition('border-color'),
  };

  const tableStyle: CSSProperties = {
    width: '100%',
    borderCollapse: 'collapse',
  };

  const thStyle = (col: DataColumn<T>): CSSProperties => ({
    padding: `${theme.space[4]}px ${theme.space[6]}px`,
    textAlign: col.align ?? 'left',
    background: theme.semantic.surface.subtle,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[13],
    fontWeight: theme.fontWeight.semibold,
    color: theme.semantic.text.secondary,
    lineHeight: 1.4,
    width: col.width,
    userSelect: 'none',
    cursor:
      (sortable && col.sortable !== false) || col.sortable
        ? 'pointer'
        : 'default',
    whiteSpace: 'nowrap',
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    boxSizing: 'border-box',
  });

  const checkboxThStyle: CSSProperties = {
    padding: `${theme.space[4]}px ${theme.space[6]}px`,
    background: theme.semantic.surface.subtle,
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    width: 40,
    textAlign: 'center',
    boxSizing: 'border-box',
  };

  const tdStyle = (col: DataColumn<T>): CSSProperties => ({
    padding: `${theme.space[4]}px ${theme.space[6]}px`,
    textAlign: col.align ?? 'left',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    color: theme.semantic.text.primary,
    lineHeight: theme.lineHeight.normal,
    width: col.width,
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    boxSizing: 'border-box',
  });

  const checkboxTdStyle: CSSProperties = {
    padding: `${theme.space[4]}px ${theme.space[6]}px`,
    width: 40,
    textAlign: 'center',
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    boxSizing: 'border-box',
  };

  const emptyStyle: CSSProperties = {
    padding: `${theme.space[12]}px ${theme.space[7]}px`,
    textAlign: 'center',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    color: theme.semantic.text.muted,
  };

  const paginationBarStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: `${theme.space[7]}px`,
    borderTop: `1px solid ${theme.semantic.border.subtle}`,
  };

  const pageInfoStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[13],
    color: theme.semantic.text.secondary,
  };

  const pageButtonsStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: 4,
  };

  const basePageBtnStyle: CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    height: 32,
    minWidth: 32,
    padding: '0 6px',
    borderRadius: theme.radius.md,
    border: 'none',
    background: 'none',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.medium,
    lineHeight: 1,
    cursor: 'pointer',
    outline: 'none',
    boxSizing: 'border-box',
    color: theme.semantic.text.primary,
    transition: transition('background-color', 'color'),
  };

  const sortIndicator = (key: string) => {
    const isActive = sortKey === key;
    const ascColor =
      isActive && sortDir === 'asc'
        ? theme.semantic.fill.primary
        : theme.semantic.text.muted;
    const descColor =
      isActive && sortDir === 'desc'
        ? theme.semantic.fill.primary
        : theme.semantic.text.muted;

    const arrowStyle: CSSProperties = {
      display: 'inline-flex',
      flexDirection: 'column',
      marginLeft: 4,
      fontSize: 9,
      lineHeight: 1,
      verticalAlign: 'middle',
    };

    return (
      <span style={arrowStyle}>
        <span style={{ color: ascColor }}>{'▲'}</span>
        <span style={{ color: descColor }}>{'▼'}</span>
      </span>
    );
  };

  // Checkbox rendering
  const renderCheckbox = (
    checked: boolean,
    indeterminate: boolean,
    onChange: () => void,
  ) => {
    const boxStyle: CSSProperties = {
      width: 16,
      height: 16,
      borderRadius: theme.radius.xs,
      border: `1.5px solid ${
        checked || indeterminate
          ? theme.semantic.fill.primary
          : theme.semantic.border.default
      }`,
      background:
        checked || indeterminate
          ? theme.semantic.fill.primary
          : theme.semantic.surface.card,
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      boxSizing: 'border-box',
      transition: transition('background', 'border-color'),
      flexShrink: 0,
      verticalAlign: 'middle',
    };

    const markStyle: CSSProperties = {
      color: theme.semantic.text.inverse,
      fontSize: 10,
      lineHeight: 1,
      fontWeight: theme.fontWeight.bold,
      visibility: checked || indeterminate ? 'visible' : 'hidden',
    };

    return (
      <div
        style={boxStyle}
        onClick={(e) => {
          e.stopPropagation();
          onChange();
        }}
        role="checkbox"
        aria-checked={indeterminate ? 'mixed' : checked}
        tabIndex={0}
      >
        <span style={markStyle}>{indeterminate ? '—' : '✓'}</span>
      </div>
    );
  };

  // Row hover state managed per-row via RowComponent
  function DataRow({ row, index }: { row: T; index: number }) {
    const [hovered, setHovered] = useState(false);

    const rowStyle: CSSProperties = {
      background: hovered ? theme.semantic.surface.hover : undefined,
      cursor: onRowClick ? 'pointer' : undefined,
      transition: `background ${theme.duration.fast}ms ${theme.easing.standard}`,
    };

    return (
      <tr
        style={rowStyle}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onClick={() => onRowClick?.(row)}
      >
        {selectable && (
          <td style={checkboxTdStyle}>
            {renderCheckbox(isRowSelected(row), false, () => toggleRow(row))}
          </td>
        )}
        {columns.map((col) => {
          const value = getCellValue(row, col.key);
          return (
            <td key={col.key} style={tdStyle(col)}>
              {col.render ? col.render(value, row) : (value as ReactNode)}
            </td>
          );
        })}
      </tr>
    );
  }

  // Page buttons
  const renderPageButtons = () => {
    const buttons: ReactNode[] = [];

    // Previous
    const prevDisabled = safePage <= 1;
    buttons.push(
      <button
        key="prev"
        type="button"
        style={{
          ...basePageBtnStyle,
          color: prevDisabled
            ? theme.semantic.text.muted
            : theme.semantic.text.primary,
          cursor: prevDisabled ? 'default' : 'pointer',
          opacity: prevDisabled ? 0.5 : 1,
          pointerEvents: prevDisabled ? 'none' : undefined,
        }}
        disabled={prevDisabled}
        aria-label="Previous page"
        onClick={() => setPage(safePage - 1)}
      >
        {'←'}
      </button>,
    );

    // Page numbers
    for (let i = 1; i <= totalPages; i++) {
      const isActive = i === safePage;
      buttons.push(
        <button
          key={i}
          type="button"
          style={{
            ...basePageBtnStyle,
            backgroundColor: isActive
              ? theme.semantic.fill.primary
              : 'transparent',
            color: isActive ? '#fff' : theme.semantic.text.primary,
            cursor: isActive ? 'default' : 'pointer',
          }}
          aria-label={`Page ${i}`}
          aria-current={isActive ? 'page' : undefined}
          onClick={() => setPage(i)}
        >
          {i}
        </button>,
      );
    }

    // Next
    const nextDisabled = safePage >= totalPages;
    buttons.push(
      <button
        key="next"
        type="button"
        style={{
          ...basePageBtnStyle,
          color: nextDisabled
            ? theme.semantic.text.muted
            : theme.semantic.text.primary,
          cursor: nextDisabled ? 'default' : 'pointer',
          opacity: nextDisabled ? 0.5 : 1,
          pointerEvents: nextDisabled ? 'none' : undefined,
        }}
        disabled={nextDisabled}
        aria-label="Next page"
        onClick={() => setPage(safePage + 1)}
      >
        {'→'}
      </button>,
    );

    return buttons;
  };

  return (
    <div ref={ref} style={wrapperStyle}>
      {filterable && (
        <div style={filterStyle}>
          <input
            type="text"
            placeholder="Filter..."
            value={filter}
            onChange={(e) => {
              setFilter(e.target.value);
              setPage(1);
            }}
            style={filterInputStyle}
            aria-label="Filter table"
          />
        </div>
      )}

      <div style={{ overflowX: 'auto' }}>
        <table style={tableStyle}>
          <thead>
            <tr>
              {selectable && (
                <th style={checkboxThStyle}>
                  {renderCheckbox(allSelected, someSelected, toggleAll)}
                </th>
              )}
              {columns.map((col) => {
                const isSortable =
                  (sortable && col.sortable !== false) || col.sortable;
                return (
                  <th
                    key={col.key}
                    style={thStyle(col)}
                    onClick={() => isSortable && handleSort(col.key)}
                    aria-sort={
                      sortKey === col.key && sortDir
                        ? sortDir === 'asc'
                          ? 'ascending'
                          : 'descending'
                        : undefined
                    }
                  >
                    {col.header}
                    {isSortable && sortIndicator(col.key)}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {displayedData.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length + (selectable ? 1 : 0)}
                  style={emptyStyle}
                >
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              displayedData.map((row, index) => (
                <DataRow key={index} row={row} index={index} />
              ))
            )}
          </tbody>
        </table>
      </div>

      {paginated && totalPages > 1 && (
        <div style={paginationBarStyle}>
          <span style={pageInfoStyle}>
            Showing {startItem}–{endItem} of {totalItems}
          </span>
          <div style={pageButtonsStyle}>{renderPageButtons()}</div>
        </div>
      )}
    </div>
  );
}

import { useState, useRef, useEffect, type CSSProperties } from 'react';
import { useClickOutside, useTheme } from 'jind-ui-kit';

export interface DateInputProps {
  value?: Date | null;
  onChange?: (date: Date | null) => void;
  placeholder?: string;
  disabled?: boolean;
  style?: CSSProperties;
}

export interface DateRangeInputProps {
  startDate?: Date | null;
  endDate?: Date | null;
  onChange?: (start: Date | null, end: Date | null) => void;
  startPlaceholder?: string;
  endPlaceholder?: string;
  disabled?: boolean;
  style?: CSSProperties;
}

const DAY_LABELS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];
const MONTH_SHORT = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];

function isSameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

function isBetween(date: Date, start: Date, end: Date): boolean {
  const t = date.getTime();
  const s = Math.min(start.getTime(), end.getTime());
  const e = Math.max(start.getTime(), end.getTime());
  return t > s && t < e;
}

function formatDate(date: Date): string {
  return `${MONTH_SHORT[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
}

function getDaysInMonth(year: number, month: number): number {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstDayOfWeek(year: number, month: number): number {
  return new Date(year, month, 1).getDay();
}

interface DayCell {
  date: Date;
  day: number;
  isCurrentMonth: boolean;
}

function buildGrid(year: number, month: number): DayCell[] {
  const first = getFirstDayOfWeek(year, month);
  const days = getDaysInMonth(year, month);
  const prevDays = getDaysInMonth(year, month - 1);
  const cells: DayCell[] = [];

  for (let i = first - 1; i >= 0; i--)
    cells.push({ date: new Date(year, month - 1, prevDays - i), day: prevDays - i, isCurrentMonth: false });
  for (let d = 1; d <= days; d++)
    cells.push({ date: new Date(year, month, d), day: d, isCurrentMonth: true });
  const rem = 7 - (cells.length % 7);
  if (rem < 7)
    for (let d = 1; d <= rem; d++)
      cells.push({ date: new Date(year, month + 1, d), day: d, isCurrentMonth: false });

  return cells;
}

interface InlineCalendarProps {
  selected?: Date | null;
  rangeStart?: Date | null;
  rangeEnd?: Date | null;
  hovered?: Date | null;
  onSelect: (date: Date) => void;
  onHover?: (date: Date | null) => void;
  onClear?: () => void;
}

function InlineCalendar({ selected, rangeStart, rangeEnd, hovered, onSelect, onHover, onClear }: InlineCalendarProps) {
  const theme = useTheme();
  const today = new Date();
  const initDate = selected ?? rangeStart ?? today;
  const [viewYear, setViewYear] = useState(initDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(initDate.getMonth());

  useEffect(() => {
    const d = selected ?? rangeStart;
    if (d) {
      setViewYear(d.getFullYear());
      setViewMonth(d.getMonth());
    }
  }, [selected, rangeStart]);

  const cells = buildGrid(viewYear, viewMonth);

  function nav(delta: number) {
    let m = viewMonth + delta;
    let y = viewYear;
    if (m < 0) { m = 11; y--; }
    else if (m > 11) { m = 0; y++; }
    setViewMonth(m);
    setViewYear(y);
  }

  const navBtn: CSSProperties = {
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    width: 32,
    height: 32,
    borderRadius: theme.radius.sm,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: 18,
    color: theme.semantic.text.primary,
    transition: `background ${theme.duration.fast}ms`,
  };

  return (
    <div style={{ width: 320, fontFamily: theme.fontFamily.sans }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '4px 0 12px' }}>
        <button type="button" style={navBtn} onClick={() => nav(-1)}
          onMouseEnter={e => { (e.currentTarget as HTMLElement).style.background = theme.semantic.surface.hover; }}
          onMouseLeave={e => { (e.currentTarget as HTMLElement).style.background = 'transparent'; }}
        >&#8249;</button>
        <span style={{ fontSize: 15, fontWeight: theme.fontWeight.semibold, color: theme.semantic.text.primary }}>
          {MONTH_NAMES[viewMonth]} {viewYear}
        </span>
        <button type="button" style={navBtn} onClick={() => nav(1)}
          onMouseEnter={e => { (e.currentTarget as HTMLElement).style.background = theme.semantic.surface.hover; }}
          onMouseLeave={e => { (e.currentTarget as HTMLElement).style.background = 'transparent'; }}
        >&#8250;</button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
        {DAY_LABELS.map((l, i) => (
          <div key={i} style={{
            height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 12, fontWeight: theme.fontWeight.medium, color: theme.semantic.text.muted,
          }}>{l}</div>
        ))}

        {cells.map((cell, i) => {
          const isSel = selected && isSameDay(cell.date, selected);
          const isToday = isSameDay(cell.date, today);
          const isRangeStart = rangeStart && isSameDay(cell.date, rangeStart);
          const isRangeEnd = rangeEnd && isSameDay(cell.date, rangeEnd);
          const isHoveredEnd = !rangeEnd && hovered && rangeStart && isSameDay(cell.date, hovered);
          const effectiveEnd = rangeEnd ?? hovered;
          const inRange = rangeStart && effectiveEnd && isBetween(cell.date, rangeStart, effectiveEnd);

          let bg = 'transparent';
          let fg = cell.isCurrentMonth ? theme.semantic.text.primary : theme.semantic.text.muted;
          let radius = theme.radius.sm;
          let fontW = isToday ? theme.fontWeight.bold : theme.fontWeight.medium;

          if (isSel || isRangeStart || isRangeEnd) {
            bg = theme.semantic.fill.primary;
            fg = theme.semantic.text.inverse;
          } else if (isHoveredEnd && cell.isCurrentMonth) {
            bg = theme.semantic.fill.primary;
            fg = theme.semantic.text.inverse;
          } else if (inRange && cell.isCurrentMonth) {
            bg = theme.semantic.surface.selected;
          }

          const endLike = isRangeEnd || isHoveredEnd;
          let borderRadiusVal: string = `${radius}px`;
          if (inRange && !isRangeStart && !endLike) borderRadiusVal = '0';
          if (isRangeStart) borderRadiusVal = `${radius}px 0 0 ${radius}px`;
          if (endLike) borderRadiusVal = `0 ${radius}px ${radius}px 0`;
          if (isRangeStart && endLike) borderRadiusVal = `${radius}px`;

          return (
            <button
              key={i}
              type="button"
              onClick={() => onSelect(cell.date)}
              onMouseEnter={() => onHover?.(cell.date)}
              onMouseLeave={() => onHover?.(null)}
              style={{
                width: 44, height: 36,
                border: isToday && !isSel && !isRangeStart && !isRangeEnd
                  ? `1.5px solid ${theme.semantic.border.focus}` : '1.5px solid transparent',
                borderRadius: borderRadiusVal,
                background: bg,
                color: fg,
                fontWeight: fontW,
                fontSize: 13,
                fontFamily: theme.fontFamily.sans,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: 0,
                boxSizing: 'border-box',
                transition: `background ${theme.duration.fast}ms`,
              }}
            >
              {cell.day}
            </button>
          );
        })}
      </div>

      {onClear && (
        <div style={{ borderTop: `1px solid ${theme.semantic.border.subtle}`, marginTop: 8, paddingTop: 8, display: 'flex', justifyContent: 'flex-end' }}>
          <button type="button" onClick={onClear} style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: theme.semantic.text.link, fontSize: 13, fontWeight: theme.fontWeight.medium,
            fontFamily: theme.fontFamily.sans, padding: '4px 8px',
          }}>Clear</button>
        </div>
      )}
    </div>
  );
}

function TriggerShell({
  children,
  open,
  disabled,
  onClick,
  style,
}: {
  children: React.ReactNode;
  open: boolean;
  disabled: boolean;
  onClick: () => void;
