import {
  useState,
  type ElementType,
  type CSSProperties,
  type Ref,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface IconButtonOwnProps {
  name: string;
  variant?: 'tile' | 'ghost';
  tone?: 'default' | 'danger';
  size?: 'lg' | 'md' | 'sm';
  disabled?: boolean;
  label?: string;
  as?: ElementType;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export type IconButtonProps<E extends ElementType = 'button'> =
  IconButtonOwnProps &
    Omit<React.ComponentPropsWithoutRef<E>, keyof IconButtonOwnProps>;

const sizeConfig = {
  lg: { box: 44, icon: 24, radius: 8 },
  md: { box: 40, icon: 20, radius: 5 },
  sm: { box: 28, icon: 18, radius: 5 },
} as const;

export function IconButton({
  as: Component = 'button',
  name,
  variant = 'tile',
  tone = 'default',
  size = 'md',
  disabled = false,
  label,
  style,
  ref,
  onClick,
  ...rest
}: IconButtonProps) {
  const theme = useTheme();
  const [hovered, setHovered] = useState(false);
  const [active, setActive] = useState(false);
  const [focused, setFocused] = useState(false);

  const config = sizeConfig[size];

  const transitionValue = transition(
    'background-color',
    'border-color',
    'box-shadow',
    'color',
  );

  function getIconColor(): string {
    if (disabled) {
      return tone === 'danger'
        ? theme.semantic.icon.danger
        : theme.semantic.icon.default;
    }
    if (tone === 'danger') {
      return hovered || active
        ? theme.colors.red[600]
        : theme.semantic.icon.danger;
    }
    return theme.semantic.icon.default;
  }

  function getVariantStyles(): CSSProperties {
    if (variant === 'tile') {
      let background = theme.semantic.surface.card;
      if (!disabled) {
        if (active) {
          background = theme.semantic.surface.pressed;
        } else if (hovered) {
          background = theme.semantic.surface.subtle;
        }
      }

      return {
        background,
        border: `1px solid ${theme.semantic.border.subtle}`,
        boxShadow: theme.shadow.sm,
      };
    }

    // ghost
    let background = 'transparent';
    if (!disabled) {
      if (active) {
        background = theme.semantic.surface.pressed;
      } else if (hovered) {
        background = theme.colors.gray[100];
      }
    }

    return {
      background,
      border: '1px solid transparent',
    };
  }

  const variantStyles = getVariantStyles();
  const iconColor = getIconColor();

  let boxShadow = variantStyles.boxShadow as string | undefined;
  if (focused && !disabled) {
    boxShadow = boxShadow
      ? `${boxShadow}, ${theme.focusRing.primary}`
      : theme.focusRing.primary;
  }

  const buttonStyle: CSSProperties = mergeStyles(
    {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 0,
      width: config.box,
      height: config.box,
      borderRadius: config.radius,
      cursor: disabled ? 'not-allowed' : 'pointer',
      outline: 'none',
      boxSizing: 'border-box',
      transition: transitionValue,
      opacity: disabled ? 0.5 : 1,
    },
    variantStyles,
    { boxShadow },
    style,
  );

  function handleMouseEnter() {
    if (!disabled) setHovered(true);
  }
  function handleMouseLeave() {
    setHovered(false);
    setActive(false);
  }
  function handleMouseDown() {
    if (!disabled) setActive(true);
  }
  function handleMouseUp() {
    setActive(false);
  }
  function handleFocus() {
    setFocused(true);
  }
  function handleBlur() {
    setFocused(false);
  }
  function handleClick(e: React.MouseEvent<HTMLButtonElement>) {
    if (disabled) return;
    (onClick as ((e: React.MouseEvent) => void) | undefined)?.(e);
  }

  return (
    <Component
      ref={ref}
      style={buttonStyle}
      disabled={Component === 'button' ? disabled : undefined}
      aria-disabled={disabled || undefined}
      aria-label={label}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onFocus={handleFocus}
      onBlur={handleBlur}
      onClick={handleClick}
      {...rest}
    >
      <i
        className={`iconoir-${name}`}
        style={{ fontSize: config.icon, color: iconColor }}
        aria-hidden="true"
      />
    </Component>
  );
}

import { useState, type CSSProperties } from 'react';
import { useControllableState, useTheme } from 'jind-ui-kit';

export interface InputProps {
  value?: string;
  defaultValue?: string;
  placeholder?: string;
  disabled?: boolean;
  iconLeft?: string;
  onChange?: (value: string) => void;
  style?: CSSProperties;
}

export function Input({
  value,
  defaultValue,
  placeholder = 'Enter a value',
  disabled = false,
  iconLeft,
  onChange,
  style,
}: InputProps) {
  const theme = useTheme();
  const [val, setVal] = useControllableState(value, defaultValue ?? '', onChange);
  const [focused, setFocused] = useState(false);

  const fieldShell: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    width: '100%',
    height: theme.controlHeight.md,
    padding: `0 ${theme.controlPadding.field}px`,
    borderRadius: theme.radius.sm,
    background: disabled
      ? theme.semantic.surface.subtle
      : focused
        ? theme.semantic.surface.card
        : theme.semantic.surface.subtle,
    border: focused
      ? `2px solid ${theme.semantic.border.focus}`
      : `1px solid ${theme.semantic.border.subtle}`,
    boxShadow: focused ? theme.focusRing.primary : theme.shadow.xs,
    color: disabled ? theme.semantic.text.muted : theme.semantic.text.primary,
    fontFamily: theme.typeVariants.label.fontFamily,
    fontSize: theme.typeVariants.label.fontSize,
    fontWeight: theme.typeVariants.label.fontWeight,
    lineHeight: theme.typeVariants.label.lineHeight,
    transition: `background-color ${theme.duration.fast}ms ${theme.easing.standard}, border-color ${theme.duration.fast}ms ${theme.easing.standard}, box-shadow ${theme.duration.fast}ms ${theme.easing.standard}`,
    opacity: disabled ? 0.6 : 1,
    cursor: disabled ? 'not-allowed' : 'text',
    boxSizing: 'border-box',
    ...style,
  };

  const iconStyle: CSSProperties = {
    fontSize: 18,
    color: theme.semantic.icon.muted,
    flexShrink: 0,
    display: 'flex',
    alignItems: 'center',
  };

  const inputStyle: CSSProperties = {
    flex: 1,
    border: 'none',
    outline: 'none',
    background: 'transparent',
    color: 'inherit',
    font: 'inherit',
    padding: 0,
    width: '100%',
    cursor: 'inherit',
  };

  return (
    <div style={fieldShell}>
      {iconLeft && <span style={iconStyle}>{iconLeft}</span>}
      <input
        style={inputStyle}
        value={val}
        placeholder={placeholder}
        disabled={disabled}
        onChange={(e) => setVal(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        data-testid="input-element"
      />
    </div>
  );
}

import { Children, cloneElement, isValidElement, type CSSProperties, type ReactNode, type ReactElement } from 'react';
import { useTheme } from 'jind-ui-kit';

export interface InputGroupProps {
  children: ReactNode;
  leftAddon?: ReactNode;
  rightAddon?: ReactNode;
  leftElement?: ReactNode;
  rightElement?: ReactNode;
  size?: 'sm' | 'md' | 'lg';
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function InputGroup({
  children,
  leftAddon,
  rightAddon,
  leftElement,
  rightElement,
  size = 'md',
  style,
  ref,
}: InputGroupProps) {
  const theme = useTheme();

  const hasLeftAddon = leftAddon !== undefined && leftAddon !== null;
  const hasRightAddon = rightAddon !== undefined && rightAddon !== null;
  const hasLeftElement = leftElement !== undefined && leftElement !== null;
  const hasRightElement = rightElement !== undefined && rightElement !== null;

  const height = theme.controlHeight[size];

  const containerStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'stretch',
    position: 'relative',
    width: '100%',
    ...style,
  };

  const addonBase: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    padding: `0 ${theme.space[6]}px`,
    background: theme.semantic.surface.subtle,
    border: `1px solid ${theme.semantic.border.default}`,
    fontSize: theme.fontSize[14],
    fontFamily: theme.fontFamily.sans,
    color: theme.semantic.text.secondary,
    boxSizing: 'border-box',
    height,
    whiteSpace: 'nowrap',
    flexShrink: 0,
  };

  const leftAddonStyle: CSSProperties = {
    ...addonBase,
    borderRight: 'none',
    borderTopLeftRadius: theme.radius.md,
    borderBottomLeftRadius: theme.radius.md,
    borderTopRightRadius: 0,
    borderBottomRightRadius: 0,
  };

  const rightAddonStyle: CSSProperties = {
    ...addonBase,
    borderLeft: 'none',
    borderTopRightRadius: theme.radius.md,
    borderBottomRightRadius: theme.radius.md,
    borderTopLeftRadius: 0,
    borderBottomLeftRadius: 0,
  };

  const elementBase: CSSProperties = {
    position: 'absolute',
    top: 0,
    bottom: 0,
    display: 'flex',
    alignItems: 'center',
    padding: `0 ${theme.space[6]}px`,
    pointerEvents: 'none',
    color: theme.semantic.text.muted,
    fontSize: theme.fontSize[14],
    zIndex: 1,
  };

  const leftElementStyle: CSSProperties = {
    ...elementBase,
    left: hasLeftAddon ? undefined : 0,
  };

  const rightElementStyle: CSSProperties = {
    ...elementBase,
    right: hasRightAddon ? undefined : 0,
  };

  // Compute extra padding for child input when elements are present
  const elementPadding = theme.space[6] * 2 + 14; // padding + approximate icon width
  const childPaddingLeft = hasLeftElement ? elementPadding : undefined;
  const childPaddingRight = hasRightElement ? elementPadding : undefined;

  // Compute border radius overrides for child
  const childBorderRadius = (() => {
    if (hasLeftAddon && hasRightAddon) return 0;
    if (hasLeftAddon)
      return `0 ${theme.radius.md}px ${theme.radius.md}px 0`;
    if (hasRightAddon)
      return `${theme.radius.md}px 0 0 ${theme.radius.md}px`;
    return undefined;
  })();

  // Clone child to inject style overrides
  const enhancedChildren = Children.map(children, (child) => {
    if (!isValidElement(child)) return child;

    const childStyle: CSSProperties = {
      ...(childBorderRadius !== undefined ? { borderRadius: childBorderRadius } : {}),
      ...(childPaddingLeft !== undefined ? { paddingLeft: childPaddingLeft } : {}),
      ...(childPaddingRight !== undefined ? { paddingRight: childPaddingRight } : {}),
      flex: 1,
      width: '100%',
    };

    return cloneElement(child as ReactElement<{ style?: CSSProperties }>, {
      style: {
        ...((child as ReactElement<{ style?: CSSProperties }>).props.style || {}),
        ...childStyle,
      },
    });
  });

  return (
    <div ref={ref} style={containerStyle} data-testid="input-group">
      {hasLeftAddon && (
        <div style={leftAddonStyle} data-testid="input-group-left-addon">
          {leftAddon}
        </div>
      )}
      <div style={{ position: 'relative', flex: 1, display: 'flex' }}>
        {hasLeftElement && (
          <div style={leftElementStyle} data-testid="input-group-left-element">
            {leftElement}
          </div>
        )}
        {enhancedChildren}
        {hasRightElement && (
          <div style={rightElementStyle} data-testid="input-group-right-element">
            {rightElement}
          </div>
        )}
      </div>
      {hasRightAddon && (
        <div style={rightAddonStyle} data-testid="input-group-right-addon">
          {rightAddon}
        </div>
      )}
    </div>
  );
}

import { useState, useRef, useCallback, type CSSProperties } from 'react';
import { transition } from 'jind-ui-kit/styles';
import { useControllableState, useTheme } from 'jind-ui-kit';

export interface InputOTPProps {
  length?: number;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  disabled?: boolean;
  error?: boolean;
  size?: 'sm' | 'md' | 'lg';
  separator?: number;
  type?: 'numeric' | 'alphanumeric';
  autoFocus?: boolean;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function InputOTP({
  length = 6,
  value,
  defaultValue,
  onChange,
  disabled = false,
  error = false,
  size = 'md',
  separator,
  type = 'numeric',
  autoFocus = false,
  style,
  ref,
}: InputOTPProps) {
  const theme = useTheme();
  const [val, setVal] = useControllableState(
    value,
    defaultValue ?? '',
    onChange,
  );
  const [focusedIndex, setFocusedIndex] = useState<number | null>(null);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const chars = val.split('').slice(0, length);
  while (chars.length < length) chars.push('');

  const isValidChar = useCallback(
    (char: string) => {
      if (type === 'numeric') return /^\d$/.test(char);
      return /^[a-zA-Z0-9]$/.test(char);
    },
    [type],
  );

  const updateValue = useCallback(
    (newChars: string[]) => {
      setVal(newChars.join(''));
    },
    [setVal],
  );

  const focusCell = useCallback((index: number) => {
    if (index >= 0 && index < length) {
      inputRefs.current[index]?.focus();
    }
  }, [length]);

  const handleChange = useCallback(
    (index: number, inputValue: string) => {
      if (disabled) return;

      // Handle paste of multiple characters
      if (inputValue.length > 1) {
        const pasteChars = inputValue.split('').filter(isValidChar).slice(0, length);
        const newChars = [...chars];
        for (let i = 0; i < pasteChars.length && index + i < length; i++) {
          newChars[index + i] = pasteChars[i];
        }
        updateValue(newChars);
        const nextIndex = Math.min(index + pasteChars.length, length - 1);
        focusCell(nextIndex);
        return;
      }

      const char = inputValue;
      if (char && !isValidChar(char)) return;

      const newChars = [...chars];
      newChars[index] = char;
      updateValue(newChars);

      if (char && index < length - 1) {
        focusCell(index + 1);
      }
    },
    [chars, disabled, isValidChar, length, updateValue, focusCell],
  );

  const handleKeyDown = useCallback(
    (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
      if (disabled) return;

      if (e.key === 'Backspace') {
        e.preventDefault();
        const newChars = [...chars];
        if (chars[index]) {
          newChars[index] = '';
          updateValue(newChars);
        } else if (index > 0) {
          newChars[index - 1] = '';
          updateValue(newChars);
          focusCell(index - 1);
        }
      } else if (e.key === 'ArrowLeft' && index > 0) {
        e.preventDefault();
        focusCell(index - 1);
      } else if (e.key === 'ArrowRight' && index < length - 1) {
        e.preventDefault();
        focusCell(index + 1);
      }
    },
    [chars, disabled, length, updateValue, focusCell],
  );

  const handlePaste = useCallback(
    (e: React.ClipboardEvent<HTMLInputElement>, index: number) => {
      e.preventDefault();
      const pasteData = e.clipboardData.getData('text');
      const pasteChars = pasteData.split('').filter(isValidChar).slice(0, length - index);
      if (pasteChars.length === 0) return;

      const newChars = [...chars];
      for (let i = 0; i < pasteChars.length; i++) {
        newChars[index + i] = pasteChars[i];
      }
      updateValue(newChars);
      const nextIndex = Math.min(index + pasteChars.length, length - 1);
      focusCell(nextIndex);
    },
    [chars, isValidChar, length, updateValue, focusCell],
  );

  const cellSize = theme.controlHeight[size];

  const containerStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    gap: theme.space[4],
    ...style,
  };

  const separatorStyle: CSSProperties = {
    color: theme.semantic.text.muted,
    fontSize: theme.fontSize[16],
    padding: `0 ${theme.space[3]}px`,
    userSelect: 'none',
  };

  const cells: React.ReactNode[] = [];
  for (let i = 0; i < length; i++) {
    if (separator !== undefined && i === separator && i > 0) {
      cells.push(
        <span key={`sep-${i}`} style={separatorStyle} data-testid="otp-separator">
          &mdash;
        </span>,
      );
    }

    const isFocused = focusedIndex === i;
    const isFilled = chars[i] !== '';

    const cellStyle: CSSProperties = {
      width: cellSize,
      height: cellSize,
      textAlign: 'center',
      fontFamily: theme.fontFamily.mono,
      fontSize: theme.fontSize[16],
      fontWeight: theme.fontWeight.medium,
      color: theme.semantic.text.primary,
      background: isFilled
        ? theme.semantic.surface.subtle
        : theme.semantic.surface.card,
      border: error
        ? `2px solid ${theme.colors.red[500]}`
        : isFocused
          ? `2px solid ${theme.semantic.border.focus}`
          : `1px solid ${theme.semantic.border.default}`,
      borderRadius: theme.radius.md,
      boxShadow: isFocused
        ? error
          ? theme.focusRing.danger
          : theme.focusRing.primary
        : 'none',
      outline: 'none',
      transition: transition('border-color', 'box-shadow', 'background-color'),
      opacity: disabled ? 0.5 : 1,
      cursor: disabled ? 'not-allowed' : 'text',
      boxSizing: 'border-box',
    };

    cells.push(
      <input
        key={i}
        ref={(el) => {
          inputRefs.current[i] = el;
        }}
        style={cellStyle}
        type="text"
        inputMode={type === 'numeric' ? 'numeric' : 'text'}
        maxLength={1}
        value={chars[i]}
        disabled={disabled}
        autoFocus={autoFocus && i === 0}
        data-testid="otp-cell"
        onChange={(e) => handleChange(i, e.target.value)}
        onKeyDown={(e) => handleKeyDown(i, e)}
        onFocus={() => setFocusedIndex(i)}
        onBlur={() => setFocusedIndex(null)}
        onPaste={(e) => handlePaste(e, i)}
      />,
    );
  }

  return (
    <div ref={ref} style={containerStyle} data-testid="otp-container">
      {cells}
    </div>
  );
}

import { type CSSProperties, type ReactNode, type Ref } from 'react';
import { useInteractionGroup } from 'jind-ui-kit';

export interface InteractionGroupProps {
  ref?: Ref<HTMLDivElement>;
  as?: 'div' | 'button' | 'a';
  children: ReactNode | ((state: { pressed: boolean; hovered: boolean; focused: boolean }) => ReactNode);
  style?: CSSProperties;
  className?: string;
  disabled?: boolean;
  onClick?: () => void;
}

export function InteractionGroup({
  ref,
  as: Tag = 'div',
  children,
  style,
  className,
  disabled,
  onClick,
}: InteractionGroupProps) {
  const { state, handlers, Provider } = useInteractionGroup();

  return (
    <Provider value={state}>
      <Tag
        ref={ref as Ref<HTMLDivElement> & Ref<HTMLButtonElement> & Ref<HTMLAnchorElement>}
        style={style}
        className={className}
        onClick={disabled ? undefined : onClick}
        onMouseDown={disabled ? undefined : handlers.onMouseDown}
        onMouseUp={disabled ? undefined : handlers.onMouseUp}
        onMouseEnter={disabled ? undefined : handlers.onMouseEnter}
        onMouseLeave={disabled ? undefined : handlers.onMouseLeave}
        onFocus={disabled ? undefined : handlers.onFocus}
        onBlur={disabled ? undefined : handlers.onBlur}
      >
        {typeof children === 'function' ? children(state) : children}
      </Tag>
    </Provider>
  );
}

import { type CSSProperties, type ReactNode, type Ref } from 'react';
