          {label}
        </span>
      )}
    </div>
  );
}

import { type CSSProperties, type Ref } from 'react';
import { useTheme } from 'jind-ui-kit';

export interface StepItem {
  label: string;
  description?: string;
}

export interface StepperProps {
  ref?: Ref<HTMLDivElement>;
  steps: StepItem[];
  activeStep: number;
  orientation?: 'horizontal' | 'vertical';
  onStepClick?: (index: number) => void;
  style?: CSSProperties;
}

type StepStatus = 'completed' | 'active' | 'pending';

function getStepStatus(index: number, activeStep: number): StepStatus {
  if (index < activeStep) return 'completed';
  if (index === activeStep) return 'active';
  return 'pending';
}

export function Stepper({
  ref,
  steps,
  activeStep,
  orientation = 'horizontal',
  onStepClick,
  style,
}: StepperProps) {
  const theme = useTheme();
  const isHorizontal = orientation === 'horizontal';

  const containerStyle: CSSProperties = {
    display: 'flex',
    flexDirection: isHorizontal ? 'row' : 'column',
    alignItems: isHorizontal ? 'flex-start' : 'stretch',
    ...style,
  };

  return (
    <div ref={ref} style={containerStyle}>
      {steps.map((step, index) => {
        const status = getStepStatus(index, activeStep);
        const isLast = index === steps.length - 1;
        const clickable = status === 'completed' && onStepClick != null;

        return (
          <StepNode
            key={index}
            step={step}
            index={index}
            status={status}
            isLast={isLast}
            isHorizontal={isHorizontal}
            clickable={clickable}
            onStepClick={onStepClick}
            theme={theme}
          />
        );
      })}
    </div>
  );
}

interface StepNodeProps {
  step: StepItem;
  index: number;
  status: StepStatus;
  isLast: boolean;
  isHorizontal: boolean;
  clickable: boolean;
  onStepClick: ((index: number) => void) | undefined;
  theme: ReturnType<typeof useTheme>;
}

function StepNode({
  step,
  index,
  status,
  isLast,
  isHorizontal,
  clickable,
  onStepClick,
  theme,
}: StepNodeProps) {
  const CIRCLE_SIZE = 28;

  const circleBackgroundColor =
    status === 'completed'
      ? theme.colors.green[500]
      : status === 'active'
        ? theme.colors.blue[500]
        : 'transparent';

  const circleBorderColor =
    status === 'completed'
      ? theme.colors.green[500]
      : status === 'active'
        ? theme.colors.blue[500]
        : theme.colors.gray[300];

  const circleTextColor =
    status === 'completed' || status === 'active'
      ? '#ffffff'
      : theme.colors.gray[400];

  const connectorColor =
    status === 'completed'
      ? theme.colors.green[500]
      : status === 'active'
        ? theme.colors.blue[500]
        : theme.colors.gray[200];

  const labelColor =
    status === 'active'
      ? theme.semantic.text.primary
      : status === 'completed'
        ? theme.semantic.text.primary
        : theme.semantic.text.muted;

  const descriptionColor = theme.semantic.text.muted;

  const circleStyle: CSSProperties = {
    width: CIRCLE_SIZE,
    height: CIRCLE_SIZE,
    borderRadius: theme.radius.full,
    backgroundColor: circleBackgroundColor,
    border: `2px solid ${circleBorderColor}`,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
    boxSizing: 'border-box',
  };

  const circleTextStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[13],
    fontWeight: theme.fontWeight.bold,
    color: circleTextColor,
    lineHeight: 1,
    userSelect: 'none',
  };

  const labelStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: status === 'active' ? theme.fontWeight.medium : theme.fontWeight.regular,
    color: labelColor,
    lineHeight: 1.4,
  };

  const descriptionStyle: CSSProperties = {
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[13],
    fontWeight: theme.fontWeight.regular,
    color: descriptionColor,
    lineHeight: 1.4,
    marginTop: 2,
  };

  if (isHorizontal) {
    const stepWrapperStyle: CSSProperties = {
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      flex: isLast ? '0 0 auto' : '1 1 0',
    };

    const labelGroupStyle: CSSProperties = {
      marginLeft: 8,
      display: 'flex',
      flexDirection: 'column',
      whiteSpace: 'nowrap',
    };

    const connectorStyle: CSSProperties = {
      flex: 1,
      height: 2,
      backgroundColor: connectorColor,
      marginLeft: 8,
      marginRight: 8,
      alignSelf: 'center',
      minWidth: 16,
    };

    const handleClick = clickable
      ? () => onStepClick?.(index)
      : undefined;

    return (
      <div style={stepWrapperStyle}>
        <div
          style={{
            display: 'flex',
            flexDirection: 'row',
            alignItems: 'center',
            cursor: clickable ? 'pointer' : 'default',
          }}
          onClick={handleClick}
        >
          <div style={circleStyle}>
            {status === 'completed' ? (
              <span style={circleTextStyle}>{'✓'}</span>
            ) : (
              <span style={circleTextStyle}>{index + 1}</span>
            )}
          </div>
          <div style={labelGroupStyle}>
            <span style={labelStyle}>{step.label}</span>
            {step.description != null && (
              <span style={descriptionStyle}>{step.description}</span>
            )}
          </div>
        </div>
        {!isLast && <div style={connectorStyle} />}
      </div>
    );
  }

  // Vertical orientation
  const stepWrapperStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'stretch',
  };

  const circleColumnStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    width: CIRCLE_SIZE,
    flexShrink: 0,
  };

  const verticalConnectorStyle: CSSProperties = {
    width: 2,
    flex: 1,
    backgroundColor: connectorColor,
    marginTop: 4,
    marginBottom: 4,
    minHeight: 20,
  };

  const labelGroupStyle: CSSProperties = {
    marginLeft: 12,
    display: 'flex',
    flexDirection: 'column',
    paddingBottom: isLast ? 0 : 24,
  };

  const handleClick = clickable
    ? () => onStepClick?.(index)
    : undefined;

  return (
    <div style={stepWrapperStyle}>
      <div style={circleColumnStyle}>
        <div
          style={{
            ...circleStyle,
            cursor: clickable ? 'pointer' : 'default',
          }}
          onClick={handleClick}
        >
          {status === 'completed' ? (
            <span style={circleTextStyle}>{'✓'}</span>
          ) : (
            <span style={circleTextStyle}>{index + 1}</span>
          )}
        </div>
        {!isLast && <div style={verticalConnectorStyle} />}
      </div>
      <div
        style={{
          ...labelGroupStyle,
          cursor: clickable ? 'pointer' : 'default',
        }}
        onClick={handleClick}
      >
        <span style={labelStyle}>{step.label}</span>
        {step.description != null && (
          <span style={descriptionStyle}>{step.description}</span>
        )}
      </div>
    </div>
  );
}

import { CSSProperties } from 'react';
import { useControllableState, useTheme } from 'jind-ui-kit';

export interface SwitchProps {
  checked?: boolean;
  defaultChecked?: boolean;
  disabled?: boolean;
  onChange?: (checked: boolean) => void;
  label?: string;
  borderRadius?: number;
  style?: CSSProperties;
}

export function Switch({
  checked,
  defaultChecked,
  disabled = false,
  onChange,
  label,
  borderRadius = 999,
  style,
}: SwitchProps) {
  const theme = useTheme();
  const [isOn, setIsOn] = useControllableState(
    checked,
    defaultChecked ?? false,
    onChange,
  );

  const handleToggle = () => {
    if (!disabled) {
      setIsOn(!isOn);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleToggle();
    }
  };

  const trackStyle: CSSProperties = {
    position: 'relative',
    width: 46,
    height: 26,
    borderRadius,
    background: isOn
      ? theme.semantic.fill.primary
      : theme.colors.gray[200],
    cursor: disabled ? 'not-allowed' : 'pointer',
    transition: `background-color ${theme.duration.base}ms ${theme.easing.standard}`,
    flexShrink: 0,
  };

  const knobStyle: CSSProperties = {
    position: 'absolute',
    top: 3,
    left: isOn ? 23 : 3,
    width: 20,
    height: 20,
    borderRadius,
    background: theme.colors.gray[0],
    boxShadow: '0 1px 3px rgba(0,0,0,0.15)',
    transition: `left ${theme.duration.base}ms ${theme.easing.standard}`,
  };

  const track = (
    <div
      data-testid="switch-track"
      role="switch"
      aria-checked={isOn}
      tabIndex={0}
      onClick={handleToggle}
      onKeyDown={handleKeyDown}
      style={label ? trackStyle : { ...trackStyle, ...style }}
    >
      <span style={knobStyle} />
    </div>
  );

  if (!label) {
    return track;
  }

  const labelWrapperStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    cursor: disabled ? 'not-allowed' : 'pointer',
    opacity: disabled ? 0.6 : 1,
    userSelect: 'none',
    ...style,
  };

  const labelTextStyle: CSSProperties = {
    fontFamily: theme.typeVariants.label.fontFamily,
    fontSize: theme.typeVariants.label.fontSize,
    fontWeight: theme.typeVariants.label.fontWeight,
    lineHeight: theme.typeVariants.label.lineHeight,
    color: theme.semantic.text.primary,
  };

  return (
    <label style={labelWrapperStyle}>
      {track}
      <span style={labelTextStyle}>{label}</span>
    </label>
  );
}

import {
  useState,
  type CSSProperties,
  type ReactNode,
  type Ref,
  type TdHTMLAttributes,
  type ThHTMLAttributes,
} from 'react';
