/* ─── TableRow ─── */

export interface TableRowProps {
  children: ReactNode;
  onClick?: () => void;
  style?: CSSProperties;
  ref?: Ref<HTMLTableRowElement>;
}

export function TableRow(
  { children, onClick, style, ref, ...rest }: TableRowProps,
) {
  const theme = useTheme();
  const [hovered, setHovered] = useState(false);

  const rowStyle: CSSProperties = {
    height: 56,
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    background: hovered ? theme.semantic.surface.hover : undefined,
    cursor: onClick ? 'pointer' : undefined,
    transition: `background ${theme.duration.fast}ms ${theme.easing.standard}`,
    ...style,
  };

  return (
    <tr
      ref={ref}
      style={rowStyle}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={onClick}
      {...rest}
    >
      {children}
    </tr>
  );
}

/* ─── TableCell ─── */

export interface TableCellProps {
  children?: ReactNode;
  align?: 'left' | 'center' | 'right';
  width?: number | string;
  header?: boolean;
  style?: CSSProperties;
  ref?: Ref<HTMLTableCellElement>;
}

export function TableCell(
  { children, align = 'left', width, header = false, style, ref, ...rest }: TableCellProps,
) {
  const theme = useTheme();
  const variant = header ? theme.typeVariants.label : theme.typeVariants.body;

  const cellStyle: CSSProperties = {
    padding: '0 14px',
    textAlign: align,
    verticalAlign: 'middle',
    width,
    fontFamily: variant.fontFamily,
    fontSize: variant.fontSize,
    fontWeight: header ? theme.fontWeight.medium : variant.fontWeight,
    lineHeight: variant.lineHeight,
    color: header ? theme.semantic.text.muted : theme.semantic.text.primary,
    ...style,
  };

  const Component = header ? 'th' : 'td';

  return (
    <Component
      ref={ref as any}
      style={cellStyle}
      {...(rest as any)}
    >
      {children}
    </Component>
  );
}

import {
  createContext,
  useContext,
  type CSSProperties,
  type ReactNode,
  useState,
} from 'react';
import { useControllableState, useTheme } from 'jind-ui-kit';

/* ─── Context ─── */

interface TabsContextValue {
  activeValue: string;
  onChange: (value: string) => void;
}

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabsContext() {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('Tab components must be used within <Tabs>');
  return ctx;
}

/* ─── Tabs ─── */

export interface TabsProps {
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  children: ReactNode;
}

export function Tabs({ value, defaultValue = '', onChange, children }: TabsProps) {
  const [activeValue, setActiveValue] = useControllableState(value, defaultValue, onChange);
  return (
    <TabsContext.Provider value={{ activeValue, onChange: setActiveValue }}>
      {children}
    </TabsContext.Provider>
  );
}

/* ─── TabList ─── */

export interface TabListProps {
  children: ReactNode;
  style?: CSSProperties;
}

export function TabList({ children, style }: TabListProps) {
  const theme = useTheme();

  const listStyle: CSSProperties = {
    display: 'flex',
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    gap: 0,
    margin: 0,
    padding: 0,
    ...style,
  };

  return (
    <div role="tablist" style={listStyle}>
      {children}
    </div>
  );
}

/* ─── Tab ─── */

export interface TabProps {
  value: string;
  disabled?: boolean;
  children: ReactNode;
}

export function Tab({ value, disabled = false, children }: TabProps) {
  const theme = useTheme();
  const { activeValue, onChange } = useTabsContext();
  const isActive = activeValue === value;
  const [hovered, setHovered] = useState(false);

  const textColor = isActive
    ? theme.semantic.fill.primary
    : hovered && !disabled
      ? theme.semantic.text.primary
      : theme.semantic.text.secondary;

  const tabStyle: CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '12px 16px',
    border: 'none',
    borderBottom: isActive
      ? `2px solid ${theme.semantic.fill.primary}`
      : '2px solid transparent',
    background: 'none',
    cursor: disabled ? 'not-allowed' : 'pointer',
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.medium,
    lineHeight: theme.lineHeight.normal,
    color: textColor,
    opacity: disabled ? 0.5 : 1,
    marginBottom: -1,
    boxSizing: 'border-box' as const,
  };

  return (
    <button
      role="tab"
      type="button"
      aria-selected={isActive}
      aria-disabled={disabled}
      disabled={disabled}
      style={tabStyle}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={() => {
        if (!disabled) onChange(value);
      }}
    >
      {children}
    </button>
  );
}

/* ─── TabPanel ─── */

export interface TabPanelProps {
  value: string;
  children: ReactNode;
}

export function TabPanel({ value, children }: TabPanelProps) {
  const { activeValue } = useTabsContext();
  if (activeValue !== value) return null;

  const panelStyle: CSSProperties = {
    padding: '16px 0',
  };

  return (
    <div role="tabpanel" style={panelStyle}>
      {children}
    </div>
  );
}

