import { type CSSProperties, type ReactNode, type Ref } from 'react';
import { useTheme, type Tone } from 'jind-ui-kit';

export interface ToastProps {
  tone: Tone;
  icon?: string;
  onDismiss?: () => void;
  children: ReactNode;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

function getToneColors(tone: Tone, theme: ReturnType<typeof useTheme>) {
  const { colors } = theme;
  const map: Record<Tone, { bg: string; text: string; border?: string }> = {
    neutral: { bg: colors.gray[50], text: colors.gray[700], border: colors.gray[200] },
    primary: { bg: colors.blue[50], text: colors.blue[700], border: colors.blue[200] },
    danger: { bg: colors.red[50], text: colors.red[500] },
    success: { bg: colors.green[50], text: colors.green[500] },
    warning: { bg: colors.amber[50], text: colors.amber[600] },
    info: { bg: colors.teal[50], text: colors.teal[600] },
    accent: { bg: colors.purple[50], text: colors.purple[500] },
    brand: { bg: colors.blue[50], text: colors.blue[500] },
  };
  return map[tone];
}

export function Toast(
  { tone, icon, onDismiss, children, style, ref, ...rest }: ToastProps,
) {
  const theme = useTheme();
  const toneColors = getToneColors(tone, theme);

  const containerStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    minHeight: 40,
    borderRadius: theme.radius.md,
    boxShadow: theme.shadow.card,
    padding: '14px 16px',
    background: toneColors.bg,
    color: toneColors.text,
    ...(toneColors.border && {
      border: `1px solid ${toneColors.border}`,
    }),
    boxSizing: 'border-box' as const,
    ...style,
  };

  const iconStyle: CSSProperties = {
    fontSize: 16,
    lineHeight: 1,
    flexShrink: 0,
  };

  const bodyStyle: CSSProperties = {
    flex: 1,
    fontFamily: theme.fontFamily.sans,
    fontSize: theme.fontSize[14],
    fontWeight: theme.fontWeight.regular,
    lineHeight: theme.lineHeight.normal,
    color: theme.semantic.text.primary,
  };

  const dismissStyle: CSSProperties = {
    background: 'none',
    border: 'none',
    padding: 0,
    cursor: 'pointer',
    fontSize: 16,
    lineHeight: 1,
    color: toneColors.text,
    flexShrink: 0,
  };

  return (
    <div ref={ref} role="alert" style={containerStyle} {...rest}>
      {icon && <span style={iconStyle}>{icon}</span>}
      <div style={bodyStyle}>{children}</div>
      {onDismiss && (
        <button
          type="button"
          onClick={onDismiss}
          style={dismissStyle}
          aria-label="Dismiss"
        >
          &#x2715;
        </button>
      )}
    </div>
  );
}

import {
  createContext,
  useContext,
  Children,
  cloneElement,
  isValidElement,
  type CSSProperties,
  type ReactNode,
  type ReactElement,
} from 'react';
import { useTheme } from 'jind-ui-kit';

/* ─── Context ─── */

interface ToolbarContextValue {
  activeValue: string | undefined;
  onChange: (value: string) => void;
}

const ToolbarContext = createContext<ToolbarContextValue | null>(null);

export function useToolbarContext() {
  return useContext(ToolbarContext);
}

/* ─── Toolbar ─── */

export interface ToolbarProps {
  value?: string;
  onChange?: (value: string) => void;
  children: ReactNode;
  style?: CSSProperties;
}

export function Toolbar({ value, onChange, children, style }: ToolbarProps) {
  const theme = useTheme();

  const toolbarStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'row',
    gap: 0,
    borderBottom: `1px solid ${theme.semantic.border.subtle}`,
    ...style,
  };

  const handleChange = (v: string) => {
    onChange?.(v);
  };

  return (
    <ToolbarContext.Provider value={{ activeValue: value, onChange: handleChange }}>
      <div role="toolbar" style={toolbarStyle}>
        {Children.map(children, (child) => {
          if (!isValidElement(child)) return child;
          // Inject active state based on toolbar value matching child's name prop
          const childProps = child.props as { name?: string };
          if (childProps.name !== undefined) {
            return cloneElement(child as ReactElement<any>, {
              active: value === childProps.name,
              onClick: (e: React.MouseEvent) => {
                handleChange(childProps.name!);
                // Also call original onClick if present
                const original = (child as ReactElement<any>).props.onClick;
                if (typeof original === 'function') original(e);
              },
            });
          }
          return child;
        })}
      </div>
    </ToolbarContext.Provider>
  );
}

import {
  useState,
  type ComponentPropsWithoutRef,
  type CSSProperties,
  type Ref,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface ToolbarButtonProps
  extends Omit<
    ComponentPropsWithoutRef<'button'>,
    'name' | 'style' | 'onClick'
  > {
  name: string;
  active?: boolean;
  disabled?: boolean;
  label?: string;
  accent?: string;
  style?: CSSProperties;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  ref?: Ref<HTMLButtonElement>;
}

export function ToolbarButton(
  {
    name,
    active = false,
    disabled = false,
    label,
    accent,
    style,
    onClick,
    ref,
    ...rest
  }: ToolbarButtonProps,
) {
  const theme = useTheme();
  const [hovered, setHovered] = useState(false);
  const [pressed, setPressed] = useState(false);
  const [focused, setFocused] = useState(false);

  const transitionValue = transition('background-color', 'color', 'box-shadow');

  const activeColor = accent ?? theme.semantic.fill.primary;

  let iconColor = theme.semantic.icon.default;
  if (disabled) {
    iconColor = theme.semantic.icon.muted;
  } else if (active) {
    iconColor = activeColor;
  }

  let background = 'transparent';
  if (!disabled) {
    if (pressed) {
      background = theme.semantic.surface.pressed;
    } else if (hovered) {
      background = theme.colors.gray[100];
    }
  }

  let boxShadow: string | undefined;
  if (focused && !disabled) {
    boxShadow = theme.focusRing.primary;
  }

  const buttonStyle: CSSProperties = mergeStyles(
    {
      width: 32,
      height: 32,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      position: 'relative',
      background,
      border: 'none',
      borderRadius: theme.radius.sm,
      padding: 0,
      cursor: disabled ? 'not-allowed' : 'pointer',
      outline: 'none',
      boxSizing: 'border-box',
      transition: transitionValue,
      boxShadow,
    },
    style,
  );

  const barStyle: CSSProperties = {
    position: 'absolute',
    bottom: 2,
    left: '50%',
    transform: 'translateX(-50%)',
    width: 16,
    height: 2,
    borderRadius: 1,
    backgroundColor: activeColor,
  };

  function handleMouseEnter() {
    if (!disabled) setHovered(true);
  }
  function handleMouseLeave() {
    setHovered(false);
    setPressed(false);
  }
  function handleMouseDown() {
    if (!disabled) setPressed(true);
  }
  function handleMouseUp() {
    setPressed(false);
  }
  function handleFocus() {
    setFocused(true);
  }
  function handleBlur() {
    setFocused(false);
  }
  function handleClick(e: React.MouseEvent<HTMLButtonElement>) {
    if (disabled) return;
    onClick?.(e);
  }

  return (
    <button
      ref={ref}
      style={buttonStyle}
      disabled={disabled}
      aria-label={label}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onFocus={handleFocus}
      onBlur={handleBlur}
      onClick={handleClick}
      {...rest}
    >
      <i
        className={`iconoir-${name}`}
        style={{ fontSize: 18, color: iconColor }}
        aria-hidden="true"
      />
      {active && <span data-testid="toolbar-active-bar" style={barStyle} />}
    </button>
  );
}

import {
  useState,
  useRef,
  cloneElement,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
} from 'react';
import { useTheme } from 'jind-ui-kit';

export type TooltipPlacement = 'top' | 'bottom' | 'left' | 'right';

export interface TooltipProps {
  content: ReactNode;
  placement?: TooltipPlacement;
  delay?: number;
  children: ReactElement;
}

function getPlacementStyles(placement: TooltipPlacement): CSSProperties {
  switch (placement) {
    case 'top':
      return {
        bottom: 'calc(100% + 8px)',
        left: '50%',
        transform: 'translateX(-50%)',
      };
    case 'bottom':
      return {
        top: 'calc(100% + 8px)',
        left: '50%',
        transform: 'translateX(-50%)',
      };
    case 'left':
      return {
        right: 'calc(100% + 8px)',
        top: '50%',
        transform: 'translateY(-50%)',
      };
    case 'right':
      return {
        left: 'calc(100% + 8px)',
        top: '50%',
        transform: 'translateY(-50%)',
      };
  }
}

export function Tooltip({
  content,
  placement = 'top',
  delay = 200,
  children,
}: TooltipProps) {
  const theme = useTheme();
  const [visible, setVisible] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  function handleMouseEnter() {
    timeoutRef.current = setTimeout(() => {
      setVisible(true);
    }, delay);
  }

  function handleMouseLeave() {
    if (timeoutRef.current !== null) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    setVisible(false);
  }

  const wrapperStyle: CSSProperties = {
    display: 'inline-block',
    position: 'relative',
  };

  const tooltipStyle: CSSProperties = {
    position: 'absolute',
    backgroundColor: theme.colors.gray[900],
    color: '#ffffff',
    ...theme.typeVariants.caption,
    borderRadius: theme.radius.xs,
    padding: '8px 12px',
    boxShadow: theme.shadow.sm,
    whiteSpace: 'nowrap',
    zIndex: 1000,
    pointerEvents: 'none',
    ...getPlacementStyles(placement),
  };

  return (
    <div
      style={wrapperStyle}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {cloneElement(children)}
      {visible && <div role="tooltip" style={tooltipStyle}>{content}</div>}
    </div>
  );
}

import {
  useState,
  useCallback,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { mergeStyles, transition } from 'jind-ui-kit/styles';
import { useTheme } from 'jind-ui-kit';

export interface TreeNode {
  id: string;
  label: string;
  icon?: string;
  children?: TreeNode[];
  disabled?: boolean;
}

export interface TreeViewProps {
  nodes: TreeNode[];
  defaultExpanded?: string[];
  expanded?: string[];
  onExpandChange?: (ids: string[]) => void;
  selected?: string | null;
  onSelect?: (id: string) => void;
  indentSize?: number;
  style?: CSSProperties;
  ref?: React.Ref<HTMLDivElement>;
}

export function TreeView({
  nodes,
  defaultExpanded,
  expanded: controlledExpanded,
  onExpandChange,
  selected,
  onSelect,
  indentSize = 20,
  style,
  ref,
}: TreeViewProps) {
  const theme = useTheme();
  const [internalExpanded, setInternalExpanded] = useState<string[]>(
    defaultExpanded ?? [],
  );

  const expanded = controlledExpanded ?? internalExpanded;

  const toggleExpand = useCallback(
    (id: string) => {
      const next = expanded.includes(id)
        ? expanded.filter((e) => e !== id)
        : [...expanded, id];

      if (!controlledExpanded) {
        setInternalExpanded(next);
      }
      onExpandChange?.(next);
    },
    [expanded, controlledExpanded, onExpandChange],
  );

  const transitionValue = transition('background-color');

  const containerStyle: CSSProperties = mergeStyles(
    {
      fontFamily: theme.fontFamily.sans,
      fontSize: theme.fontSize[14],
      color: theme.semantic.text.primary,
    },
    style,
  );

  function renderNode(node: TreeNode, depth: number): ReactNode {
    const hasChildren = node.children && node.children.length > 0;
    const isExpanded = expanded.includes(node.id);
    const isSelected = selected === node.id;

    const rowStyle: CSSProperties = {
      display: 'flex',
      alignItems: 'center',
      gap: 6,
      padding: '6px 8px',
      paddingLeft: depth * indentSize + 8,
      cursor: node.disabled ? 'not-allowed' : 'pointer',
      backgroundColor: isSelected
        ? theme.semantic.surface.selected
        : 'transparent',
      borderRadius: theme.radius.sm,
      transition: transitionValue,
      opacity: node.disabled ? 0.5 : 1,
      outline: 'none',
      userSelect: 'none',
    };

    const chevronStyle: CSSProperties = {
      width: 16,
      height: 16,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: 12,
      color: theme.semantic.icon.muted,
      transition: 'transform 150ms ease',
      transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
      flexShrink: 0,
    };

    const spacerStyle: CSSProperties = {
      width: 16,
      flexShrink: 0,
    };

    return (
      <div key={node.id}>
        <div
          role="treeitem"
          aria-expanded={hasChildren ? isExpanded : undefined}
          aria-selected={isSelected}
          aria-disabled={node.disabled || undefined}
          tabIndex={node.disabled ? -1 : 0}
          style={rowStyle}
          onClick={() => {
            if (node.disabled) return;
            if (hasChildren) toggleExpand(node.id);
            onSelect?.(node.id);
          }}
          onKeyDown={(e) => {
            if (node.disabled) return;
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              if (hasChildren) toggleExpand(node.id);
              onSelect?.(node.id);
            }
            if (e.key === 'ArrowRight' && hasChildren && !isExpanded) {
              e.preventDefault();
              toggleExpand(node.id);
            }
            if (e.key === 'ArrowLeft' && hasChildren && isExpanded) {
              e.preventDefault();
              toggleExpand(node.id);
            }
          }}
        >
          {hasChildren ? (
            <span style={chevronStyle} aria-hidden="true">
              {'▸'}
            </span>
          ) : (
            <span style={spacerStyle} />
          )}
          {node.icon && (
            <i
              className={`iconoir-${node.icon}`}
              style={{
                fontSize: 16,
                color: theme.semantic.icon.default,
                flexShrink: 0,
              }}
              aria-hidden="true"
            />
          )}
          <span
            style={{
              fontWeight: isSelected
                ? theme.fontWeight.semibold
                : theme.fontWeight.regular,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
            }}
          >
            {node.label}
          </span>
        </div>

        {hasChildren && isExpanded && (
          <div role="group">
            {node.children!.map((child) => renderNode(child, depth + 1))}
          </div>
        )}
      </div>
    );
  }

  return (
    <div ref={ref} role="tree" style={containerStyle}>
      {nodes.map((node) => renderNode(node, 0))}
    </div>
  );
}
